// Seerah, Meccan period: Arabia before Islam, lineage, birth and youth, revelation, persecution, Abyssinia, boycott, Ṭāʾif, Isrāʾ, ʿAqaba, Hijra. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ---------- stage 1 ----------
  { id: "srm-001", s: "seerah", g: 1, d: 1, t: ["lineage", "birth-and-childhood"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, lineage of the Prophet",
    en: ["What was the name of the Prophet Muḥammad's father?", ["ʿAbdullāh", "ʿAbd al-Muṭṭalib", "Abū Ṭālib", "Hāshim"], "His father was ʿAbdullāh ibn ʿAbd al-Muṭṭalib. ʿAbd al-Muṭṭalib was his grandfather, Abū Ṭālib his uncle and Hāshim his great-grandfather."],
    de: ["Wie hieß der Vater des Propheten Muḥammad?", ["ʿAbdullāh", "ʿAbd al-Muṭṭalib", "Abū Ṭālib", "Hāschim"], "Sein Vater war ʿAbdullāh ibn ʿAbd al-Muṭṭalib. ʿAbd al-Muṭṭalib war sein Großvater, Abū Ṭālib sein Onkel und Hāschim sein Urgroßvater."],
    ar: ["ما اسم والد النبي محمد ﷺ؟", ["عبد الله", "عبد المطلب", "أبو طالب", "هاشم"], "والده عبد الله بن عبد المطلب؛ أما عبد المطلب فجدّه، وأبو طالب عمّه، وهاشم جدّ أبيه."] },
  { id: "srm-002", s: "seerah", g: 1, d: 1, t: ["lineage", "birth-and-childhood"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, lineage of the Prophet",
    en: ["Who was the mother of the Prophet Muḥammad?", ["Āmina bint Wahb", "Ḥalīma al-Saʿdiyya", "Khadīja bint Khuwaylid", "Fāṭima bint Asad"], "His mother was Āmina bint Wahb of the clan of Zuhra. Ḥalīma was his wet nurse, Khadīja his first wife and Fāṭima bint Asad the wife of Abū Ṭālib."],
    de: ["Wer war die Mutter des Propheten Muḥammad?", ["Āmina bint Wahb", "Ḥalīma as-Saʿdiyya", "Chadīdscha bint Chuwailid", "Fāṭima bint Asad"], "Seine Mutter war Āmina bint Wahb aus dem Clan Zuhra. Ḥalīma war seine Amme, Chadīdscha seine erste Ehefrau und Fāṭima bint Asad die Frau Abū Ṭālibs."],
    ar: ["مَن أمّ النبي محمد ﷺ؟", ["آمنة بنت وهب", "حليمة السعدية", "خديجة بنت خويلد", "فاطمة بنت أسد"], "أمّه آمنة بنت وهب من بني زهرة؛ وحليمة مرضعته، وخديجة أولى زوجاته، وفاطمة بنت أسد زوجة أبي طالب."] },
  { id: "srm-003", s: "seerah", g: 1, d: 1, t: ["lineage", "pre-islamic-arabia"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, lineage of the Prophet",
    en: ["To which tribe did the Prophet Muḥammad belong?", ["Quraysh", "Thaqīf", "Khazraj", "Hawāzin"], "He was from the clan of Hāshim within Quraysh, the tribe that guarded the Kaʿba in Mecca. Thaqīf lived in al-Ṭāʾif, the Khazraj in Yathrib."],
    de: ["Zu welchem Stamm gehörte der Prophet Muḥammad?", ["Quraisch", "Thaqīf", "Chazradsch", "Hawāzin"], "Er stammte aus dem Clan Hāschim innerhalb der Quraisch, die in Mekka die Kaʿba hüteten. Die Thaqīf lebten in aṭ-Ṭāʾif, die Chazradsch in Yathrib."],
    ar: ["إلى أي قبيلة ينتسب النبي محمد ﷺ؟", ["قريش", "ثقيف", "الخزرج", "هوازن"], "هو من بني هاشم من قريش سدنة الكعبة في مكة؛ أما ثقيف فمن أهل الطائف، والخزرج من أهل يثرب."] },
  { id: "srm-004", s: "seerah", g: 1, d: 2, t: ["year-of-elephant", "pre-islamic-arabia"], src: "Ibn Kathīr, Tafsīr, on Sūrat al-Fīl", v: "105:1",
    en: ["The verse shown opens a sūra about an event in the year the Prophet was born. Which army does it refer to?", ["Abraha's army with the elephant", "The Persian army of Kisrā", "The Byzantine army at Muʾta", "The army of the Confederates"], "Sūrat al-Fīl recalls how Abraha marched on Mecca with an elephant to destroy the Kaʿba and was turned back. The Prophet was born in that same year, the Year of the Elephant."],
    de: ["Die gezeigte Āya eröffnet eine Sure über ein Ereignis im Geburtsjahr des Propheten. Auf welches Heer bezieht sie sich?", ["Das Heer Abrahas mit dem Elefanten", "Das persische Heer des Kisrā", "Das byzantinische Heer bei Muʾta", "Das Heer der Verbündeten (Aḥzāb)"], "Die Sure al-Fīl erinnert daran, wie Abraha mit einem Elefanten gegen Mekka zog, um die Kaʿba zu zerstören, und zurückgeschlagen wurde. Im selben Jahr, dem Jahr des Elefanten, wurde der Prophet geboren."],
    ar: ["الآية المعروضة مطلع سورة تتحدث عن حدث وقع في عام مولد النبي ﷺ. إلى أي جيش تشير؟", ["جيش أبرهة صاحب الفيل", "جيش كسرى الفارسي", "جيش الروم في مؤتة", "جيش الأحزاب"], "تذكّر سورة الفيل بمسير أبرهة إلى مكة بالفيل ليهدم الكعبة وكيف ردّه الله؛ وفي ذلك العام، عام الفيل، وُلد النبي ﷺ."] },
  { id: "srm-005", s: "seerah", g: 1, d: 1, t: ["birth-and-childhood", "chronology"], src: "Ṣaḥīḥ Muslim, Kitāb al-Ṣiyām, fasting on Mondays",
    en: ["On which day of the week was the Prophet born?", ["Monday", "Friday", "Thursday", "Sunday"], "When asked about fasting on Monday, the Prophet said it was the day on which he was born and on which revelation came to him (Ṣaḥīḥ Muslim)."],
    de: ["An welchem Wochentag wurde der Prophet geboren?", ["Montag", "Freitag", "Donnerstag", "Sonntag"], "Nach dem Fasten am Montag gefragt, sagte der Prophet, dies sei der Tag, an dem er geboren wurde und an dem die Offenbarung zu ihm kam (Ṣaḥīḥ Muslim)."],
    ar: ["في أي يوم من أيام الأسبوع وُلد النبي ﷺ؟", ["يوم الاثنين", "يوم الجمعة", "يوم الخميس", "يوم الأحد"], "سُئل ﷺ عن صوم يوم الاثنين فذكر أنه اليوم الذي وُلد فيه وأُنزل عليه فيه، كما في صحيح مسلم."] },
  { id: "srm-006", s: "seerah", g: 1, d: 2, t: ["birth-and-childhood", "halima"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the nursing in Banū Saʿd",
    en: ["Ḥalīma, the Prophet's wet nurse, belonged to which tribe?", ["Banū Saʿd ibn Bakr", "Banū Thaqīf", "Banū Zuhra", "Banū Makhzūm"], "Ḥalīma bint Abī Dhuʾayb was from Banū Saʿd ibn Bakr, a Bedouin tribe of Hawāzin. Meccan families sent infants to the desert for its healthy air and pure Arabic."],
    de: ["Zu welchem Stamm gehörte Ḥalīma, die Amme des Propheten?", ["Banū Saʿd ibn Bakr", "Banū Thaqīf", "Banū Zuhra", "Banū Machzūm"], "Ḥalīma bint Abī Dhuʾaib gehörte zu den Banū Saʿd ibn Bakr, einem Beduinenstamm der Hawāzin. Mekkanische Familien gaben Säuglinge wegen der gesunden Luft und des reinen Arabisch in die Wüste."],
    ar: ["إلى أي قبيلة كانت تنتمي حليمة مرضعة النبي ﷺ؟", ["بنو سعد بن بكر", "ثقيف", "بنو زهرة", "بنو مخزوم"], "حليمة بنت أبي ذؤيب من بني سعد بن بكر من هوازن، وكانت أسر مكة تسترضع أبناءها في البادية لصحة هوائها وفصاحة لسانها."] },
  { id: "srm-007", s: "seerah", g: 1, d: 2, t: ["bahira", "birth-and-childhood"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the story of Baḥīrā",
    en: ["Who was Baḥīrā, whom the young Muḥammad met on a journey with Abū Ṭālib?", ["A Christian monk near Buṣrā in Syria", "A Jewish rabbi of Yathrib", "A Persian priest of al-Ḥīra", "A soothsayer of Quraysh"], "On a trade journey to Syria with his uncle Abū Ṭālib, the caravan stopped near the hermitage of the monk Baḥīrā at Buṣrā, who recognised signs of prophethood in the boy."],
    de: ["Wer war Baḥīrā, dem der junge Muḥammad auf einer Reise mit Abū Ṭālib begegnete?", ["Ein christlicher Mönch bei Buṣrā in Syrien", "Ein jüdischer Rabbiner in Yathrib", "Ein persischer Priester in al-Ḥīra", "Ein Wahrsager der Quraisch"], "Auf einer Handelsreise nach Syrien mit seinem Onkel Abū Ṭālib machte die Karawane bei der Klause des Mönchs Baḥīrā in Buṣrā Halt; er erkannte an dem Jungen Zeichen des Prophetentums."],
    ar: ["مَن بحيرا الذي لقيه محمد ﷺ صبيًّا في رحلته مع أبي طالب؟", ["راهب نصراني قرب بُصرى بالشام", "حبر يهودي من يثرب", "كاهن فارسي من الحيرة", "كاهن عرّاف من قريش"], "في رحلة تجارية إلى الشام مع عمه أبي طالب نزلت القافلة قرب صومعة الراهب بحيرا ببُصرى، فعرف في الغلام علامات النبوة."] },
  { id: "srm-008", s: "seerah", g: 1, d: 1, t: ["character-before-prophethood", "kaaba-rebuilding"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the rebuilding of the Kaʿba",
    en: ["By which title did the people of Mecca know Muḥammad before his prophethood?", ["al-Amīn (the Trustworthy)", "al-Fārūq (the Discerner)", "al-Ṣiddīq (the Truthful Confirmer)", "Sayf Allāh (the Sword of God)"], "Quraysh called him al-Amīn because of his honesty and reliability. al-Fārūq became the title of ʿUmar, al-Ṣiddīq of Abū Bakr and Sayf Allāh of Khālid ibn al-Walīd."],
    de: ["Unter welchem Beinamen kannten die Mekkaner Muḥammad vor seinem Prophetentum?", ["al-Amīn (der Vertrauenswürdige)", "al-Fārūq (der Unterscheidende)", "aṣ-Ṣiddīq (der Wahrhaftige)", "Saif Allāh (das Schwert Gottes)"], "Die Quraisch nannten ihn wegen seiner Ehrlichkeit und Zuverlässigkeit al-Amīn. al-Fārūq wurde Beiname ʿUmars, aṣ-Ṣiddīq Abū Bakrs und Saif Allāh Chālid ibn al-Walīds."],
    ar: ["بأي لقب عرف أهل مكة محمدًا ﷺ قبل البعثة؟", ["الأمين", "الفاروق", "الصدّيق", "سيف الله"], "لقّبته قريش بالأمين لصدقه وأمانته؛ أما الفاروق فلقب عمر، والصدّيق لقب أبي بكر، وسيف الله لقب خالد بن الوليد."] },
  { id: "srm-009", s: "seerah", g: 1, d: 1, t: ["khadija"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, marriage to Khadīja",
    en: ["Who was the first wife of the Prophet?", ["Khadīja bint Khuwaylid", "ʿĀʾisha bint Abī Bakr", "Sawda bint Zamʿa", "Ḥafṣa bint ʿUmar"], "Khadīja was his first wife, and he married no one else while she lived. Sawda and ʿĀʾisha were married after her death, Ḥafṣa later in Medina."],
    de: ["Wer war die erste Ehefrau des Propheten?", ["Chadīdscha bint Chuwailid", "ʿĀʾischa bint Abī Bakr", "Sauda bint Zamʿa", "Ḥafṣa bint ʿUmar"], "Chadīdscha war seine erste Ehefrau, und solange sie lebte, heiratete er keine andere. Sauda und ʿĀʾischa heiratete er nach ihrem Tod, Ḥafṣa später in Medina."],
    ar: ["مَن أولى زوجات النبي ﷺ؟", ["خديجة بنت خويلد", "عائشة بنت أبي بكر", "سودة بنت زمعة", "حفصة بنت عمر"], "خديجة أولى زوجاته، ولم يتزوج عليها في حياتها؛ وتزوج سودة وعائشة بعد وفاتها، وحفصة لاحقًا في المدينة."] },
  { id: "srm-010", s: "seerah", g: 1, d: 2, t: ["kaaba-rebuilding", "black-stone"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the rebuilding of the Kaʿba",
    en: ["When the Prophet was about thirty-five, Quraysh rebuilt a building in Mecca. Which one?", ["The Kaʿba", "Dār al-Nadwa", "The house of Abū Ṭālib", "The well house of Zamzam"], "Commonly dated to when he was thirty-five, Quraysh rebuilt the Kaʿba after damage by flooding; it was during this rebuilding that the dispute over the Black Stone arose."],
    de: ["Als der Prophet etwa fünfunddreißig war, bauten die Quraisch ein Gebäude in Mekka neu auf. Welches?", ["Die Kaʿba", "Dār an-Nadwa", "Das Haus Abū Ṭālibs", "Das Brunnenhaus von Zamzam"], "Meist auf sein fünfunddreißigstes Lebensjahr datiert, bauten die Quraisch die durch Fluten beschädigte Kaʿba neu; dabei entstand der Streit um den Schwarzen Stein."],
    ar: ["لما بلغ النبي ﷺ نحو الخامسة والثلاثين أعادت قريش بناء بناءٍ في مكة. ما هو؟", ["الكعبة", "دار الندوة", "بيت أبي طالب", "سقاية زمزم"], "يُذكر في المشهور أنه كان في الخامسة والثلاثين حين أعادت قريش بناء الكعبة بعد أن أضرّ بها السيل، وفي هذا البناء وقع الخلاف على الحجر الأسود."] },
  { id: "srm-011", s: "seerah", g: 1, d: 1, t: ["first-revelation"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Badʾ al-Waḥy",
    en: ["In which cave did the first revelation come to the Prophet?", ["Ḥirāʾ", "Thawr", "Uḥud", "al-Ṣafā"], "He used to retreat to the cave of Ḥirāʾ on the mountain later called Jabal al-Nūr, where Jibrīl came to him. Thawr is the cave of the Hijra."],
    de: ["In welcher Höhle kam die erste Offenbarung zum Propheten?", ["Ḥirāʾ", "Thaur", "Uḥud", "aṣ-Ṣafā"], "Er zog sich in die Höhle Ḥirāʾ auf dem später Dschabal an-Nūr genannten Berg zurück, wo Dschibrīl zu ihm kam. Thaur ist die Höhle der Hidschra."],
    ar: ["في أي غار نزل الوحي أول مرة على النبي ﷺ؟", ["غار حراء", "غار ثور", "جبل أحد", "الصفا"], "كان يخلو بغار حراء في الجبل الذي سُمّي بعدُ جبل النور، وفيه جاءه جبريل؛ أما غار ثور فغار الهجرة."] },
  { id: "srm-012", s: "seerah", g: 1, d: 1, t: ["first-revelation", "chronology"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Manāqib al-Anṣār, the sending of the Prophet",
    en: ["How old was the Prophet, according to most biographers, when revelation began?", ["Forty years", "Twenty-five years", "Thirty-five years", "Fifty years"], "Ibn ʿAbbās reports that he was sent at forty (al-Bukhārī). At twenty-five he married Khadīja and at about thirty-five the Kaʿba was rebuilt."],
    de: ["Wie alt war der Prophet nach den meisten Biographen, als die Offenbarung begann?", ["Vierzig Jahre", "Fünfundzwanzig Jahre", "Fünfunddreißig Jahre", "Fünfzig Jahre"], "Ibn ʿAbbās berichtet, dass er mit vierzig gesandt wurde (al-Buchārī). Mit fünfundzwanzig heiratete er Chadīdscha, mit etwa fünfunddreißig wurde die Kaʿba neu gebaut."],
    ar: ["كم كان عمر النبي ﷺ عند بدء الوحي على قول أكثر أهل السير؟", ["أربعون سنة", "خمس وعشرون سنة", "خمس وثلاثون سنة", "خمسون سنة"], "روى البخاري عن ابن عباس أنه بُعث لأربعين؛ وفي الخامسة والعشرين تزوج خديجة، وفي نحو الخامسة والثلاثين أُعيد بناء الكعبة."] },
  { id: "srm-013", s: "seerah", g: 1, d: 1, t: ["early-muslims", "khadija"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the first to accept Islam",
    en: ["Who was the very first person to believe in the Prophet's message?", ["Khadīja", "Abū Bakr", "ʿAlī ibn Abī Ṭālib", "Zayd ibn Ḥāritha"], "Khadīja believed at once when he returned from Ḥirāʾ and comforted him. Abū Bakr was the first free adult man, ʿAlī the first boy and Zayd the first freedman."],
    de: ["Wer war der allererste Mensch, der an die Botschaft des Propheten glaubte?", ["Chadīdscha", "Abū Bakr", "ʿAlī ibn Abī Ṭālib", "Zaid ibn Ḥāritha"], "Chadīdscha glaubte sofort, als er aus Ḥirāʾ zurückkehrte, und tröstete ihn. Abū Bakr war der erste freie erwachsene Mann, ʿAlī der erste Junge, Zaid der erste Freigelassene."],
    ar: ["مَن أوّل مَن آمن برسالة النبي ﷺ على الإطلاق؟", ["خديجة", "أبو بكر", "علي بن أبي طالب", "زيد بن حارثة"], "آمنت خديجة أول ما رجع من حراء وثبّتته؛ وأبو بكر أول من أسلم من الرجال الأحرار، وعلي أول من أسلم من الصبيان، وزيد أول من أسلم من الموالي."] },
  { id: "srm-014", s: "seerah", g: 1, d: 2, t: ["public-call", "opposition-of-quraysh"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Tafsīr, Sūrat al-Masad", v: "111:1",
    en: ["The sūra that opens with the verse shown was revealed about the Prophet's uncle who rejected him at al-Ṣafā. Who was he?", ["Abū Lahab", "Abū Jahl", "Abū Sufyān", "Umayya ibn Khalaf"], "When the Prophet called the clans of Quraysh from al-Ṣafā, his uncle Abū Lahab cursed him, and Sūrat al-Masad was revealed (al-Bukhārī). Abū Jahl was of Makhzūm, not his uncle."],
    de: ["Die Sure, die mit der gezeigten Āya beginnt, wurde über den Onkel des Propheten offenbart, der ihn auf aṣ-Ṣafā zurückwies. Wer war er?", ["Abū Lahab", "Abū Dschahl", "Abū Sufyān", "Umayya ibn Chalaf"], "Als der Prophet die Clans der Quraisch von aṣ-Ṣafā aus rief, verfluchte ihn sein Onkel Abū Lahab, und die Sure al-Masad wurde offenbart (al-Buchārī). Abū Dschahl war ein Machzūmit, nicht sein Onkel."],
    ar: ["نزلت السورة التي تبدأ بالآية المعروضة في عمّ النبي ﷺ الذي ردّه على الصفا. مَن هو؟", ["أبو لهب", "أبو جهل", "أبو سفيان", "أمية بن خلف"], "لما نادى النبي ﷺ بطون قريش من على الصفا قال له عمه أبو لهب قولًا قبيحًا فنزلت سورة المسد، كما في البخاري؛ أما أبو جهل فمخزومي وليس عمّه."] },
  { id: "srm-015", s: "seerah", g: 1, d: 1, t: ["persecution", "bilal"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the persecution of the weak Muslims",
    en: ["What did Bilāl keep repeating while he was tortured in the heat of Mecca?", ["“Aḥad, aḥad” (One, One)", "“Allāhu akbar” three times", "The name of his master", "“Salām, salām” (Peace, peace)"], "Pinned under a heavy rock in the burning sun, Bilāl affirmed the oneness of God with the single word “Aḥad”, refusing to praise the idols as his tormentors demanded."],
    de: ["Was wiederholte Bilāl unablässig, während er in der Hitze Mekkas gefoltert wurde?", ["„Aḥad, aḥad“ (Einer, Einer)", "Dreimal „Allāhu akbar“", "Den Namen seines Herrn", "„Salām, salām“ (Friede, Friede)"], "Unter einem schweren Stein in der glühenden Sonne bekannte Bilāl die Einheit Gottes mit dem einen Wort „Aḥad“ und weigerte sich, die Götzen zu preisen, wie seine Peiniger es verlangten."],
    ar: ["ماذا كان بلال يردّد وهو يُعذَّب في رمضاء مكة؟", ["«أحدٌ أحد»", "«الله أكبر» ثلاثًا", "اسم سيّده", "«سلامٌ سلام»"], "كان بلال يُلقى في الرمضاء وعلى صدره الصخرة فيثبت على التوحيد بقوله «أحد أحد»، ويأبى أن يذكر الأصنام بخير كما أراد معذّبوه."] },
  { id: "srm-016", s: "seerah", g: 1, d: 2, t: ["abyssinia", "najashi"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the emigration to Abyssinia",
    en: ["What was the title of the Christian king of Abyssinia who sheltered the Muslim emigrants?", ["al-Najāshī (the Negus)", "Qayṣar (Caesar)", "Kisrā (Chosroes)", "Tubbaʿ"], "The ruler of Abyssinia bore the title al-Najāshī; the Prophet described him as a king under whom no one is wronged. Qayṣar ruled Byzantium, Kisrā Persia and Tubbaʿ was the title of the old Yemeni kings."],
    de: ["Welchen Titel trug der christliche König Abessiniens, der die muslimischen Auswanderer aufnahm?", ["an-Nadschāschī (der Negus)", "Qaiṣar (Kaiser)", "Kisrā (Chosrau)", "Tubbaʿ"], "Der Herrscher Abessiniens trug den Titel an-Nadschāschī; der Prophet beschrieb ihn als König, bei dem niemandem Unrecht geschieht. Qaiṣar herrschte über Byzanz, Kisrā über Persien, Tubbaʿ war der Titel der alten jemenitischen Könige."],
    ar: ["ما لقب ملك الحبشة النصراني الذي آوى المهاجرين المسلمين؟", ["النجاشي", "قيصر", "كسرى", "تُبَّع"], "كان ملك الحبشة يُلقَّب بالنجاشي، ووصفه النبي ﷺ بأنه ملك لا يُظلم عنده أحد؛ أما قيصر فملك الروم، وكسرى ملك فارس، وتبّع لقب ملوك اليمن القدامى."] },
  { id: "srm-017", s: "seerah", g: 1, d: 2, t: ["year-of-sorrow"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the deaths of Abū Ṭālib and Khadīja",
    en: ["The “Year of Sorrow” (ʿĀm al-Ḥuzn) is named after the deaths of which two people?", ["Abū Ṭālib and Khadīja", "Āmina and ʿAbd al-Muṭṭalib", "Ḥamza and Jaʿfar", "Sumayya and Yāsir"], "In the tenth year of prophethood the Prophet lost his protecting uncle Abū Ṭālib and his wife Khadīja within a short time. Āmina and ʿAbd al-Muṭṭalib had died in his childhood; Ḥamza and Jaʿfar fell later in battle."],
    de: ["Das „Jahr der Trauer“ (ʿĀm al-Ḥuzn) ist nach dem Tod welcher zwei Menschen benannt?", ["Abū Ṭālib und Chadīdscha", "Āmina und ʿAbd al-Muṭṭalib", "Ḥamza und Dschaʿfar", "Sumayya und Yāsir"], "Im zehnten Jahr des Prophetentums verlor der Prophet kurz nacheinander seinen schützenden Onkel Abū Ṭālib und seine Frau Chadīdscha. Āmina und ʿAbd al-Muṭṭalib starben in seiner Kindheit, Ḥamza und Dschaʿfar fielen später im Kampf."],
    ar: ["سُمّي «عام الحزن» بوفاة أيّ اثنين؟", ["أبي طالب وخديجة", "آمنة وعبد المطلب", "حمزة وجعفر", "سمية وياسر"], "في السنة العاشرة من البعثة فقد النبي ﷺ عمّه الحامي أبا طالب وزوجه خديجة في مدة قصيرة؛ أما آمنة وعبد المطلب فماتا في صغره، واستُشهد حمزة وجعفر بعد ذلك في الغزوات."] },
  { id: "srm-018", s: "seerah", g: 1, d: 1, t: ["isra-miraj"], src: "Ibn Kathīr, Tafsīr, on 17:1", v: "17:1",
    en: ["The verse shown describes the Night Journey from al-Masjid al-Ḥarām. To which mosque was the Prophet taken?", ["al-Masjid al-Aqṣā in Jerusalem", "The mosque of Qubāʾ", "The Prophet's Mosque in Medina", "The mosque of al-Khayf in Minā"], "al-Isrāʾ was the journey by night from Mecca to al-Masjid al-Aqṣā in Jerusalem, followed by the ascension (al-Miʿrāj). Qubāʾ and the Prophet's Mosque were built only after the Hijra."],
    de: ["Die gezeigte Āya beschreibt die Nachtreise von al-Masdschid al-Ḥarām. Zu welcher Moschee wurde der Prophet gebracht?", ["al-Masdschid al-Aqṣā in Jerusalem", "Die Moschee von Qubāʾ", "Die Prophetenmoschee in Medina", "Die Moschee al-Chaif in Minā"], "Al-Isrāʾ war die nächtliche Reise von Mekka nach al-Masdschid al-Aqṣā in Jerusalem, gefolgt von der Himmelfahrt (al-Miʿrādsch). Qubāʾ und die Prophetenmoschee wurden erst nach der Hidschra gebaut."],
    ar: ["تصف الآية المعروضة الإسراء من المسجد الحرام. إلى أي مسجد أُسري بالنبي ﷺ؟", ["المسجد الأقصى في بيت المقدس", "مسجد قباء", "المسجد النبوي في المدينة", "مسجد الخيف بمنى"], "الإسراء رحلة ليلية من مكة إلى المسجد الأقصى ببيت المقدس، تلاها المعراج؛ أما مسجد قباء والمسجد النبوي فلم يُبنيا إلا بعد الهجرة."] },
  { id: "srm-019", s: "seerah", g: 1, d: 1, t: ["hijra", "cave-of-thawr"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the Hijra",
    en: ["In which cave did the Prophet and Abū Bakr hide during the Hijra?", ["Thawr", "Ḥirāʾ", "al-Kahf", "Abū Qubays"], "They hid for three nights in the cave of Thawr, south of Mecca, while Quraysh searched the routes north toward Yathrib. Ḥirāʾ is the cave of the first revelation."],
    de: ["In welcher Höhle versteckten sich der Prophet und Abū Bakr während der Hidschra?", ["Thaur", "Ḥirāʾ", "al-Kahf", "Abū Qubais"], "Sie verbargen sich drei Nächte in der Höhle Thaur südlich von Mekka, während die Quraisch die Wege nach Norden Richtung Yathrib absuchten. Ḥirāʾ ist die Höhle der ersten Offenbarung."],
    ar: ["في أي غار اختبأ النبي ﷺ وأبو بكر أثناء الهجرة؟", ["غار ثور", "غار حراء", "غار الكهف", "جبل أبي قبيس"], "مكثا في غار ثور جنوب مكة ثلاث ليال بينما كانت قريش تطلبهما في طرق الشمال نحو يثرب؛ أما حراء فغار أول الوحي."] },
  { id: "srm-020", s: "seerah", g: 1, d: 1, t: ["hijra", "cave-of-thawr"], src: "Ibn Kathīr, Tafsīr, on 9:40", v: "9:40",
    en: ["The verse shown speaks of the Prophet and his companion in the cave during the Hijra. Who was that companion?", ["Abū Bakr al-Ṣiddīq", "ʿUmar ibn al-Khaṭṭāb", "ʿAlī ibn Abī Ṭālib", "Zayd ibn Ḥāritha"], "The verse refers to the second of two in the cave of Thawr, and the exegetes agree that the companion was Abū Bakr. ʿAlī stayed behind in Mecca in the Prophet's bed."],
    de: ["Die gezeigte Āya spricht vom Propheten und seinem Gefährten in der Höhle während der Hidschra. Wer war dieser Gefährte?", ["Abū Bakr aṣ-Ṣiddīq", "ʿUmar ibn al-Chaṭṭāb", "ʿAlī ibn Abī Ṭālib", "Zaid ibn Ḥāritha"], "Die Āya meint den Zweiten von zweien in der Höhle Thaur; die Exegeten sind sich einig, dass es Abū Bakr war. ʿAlī blieb in Mekka im Bett des Propheten zurück."],
    ar: ["تتحدث الآية المعروضة عن النبي ﷺ وصاحبه في الغار أثناء الهجرة. مَن هذا الصاحب؟", ["أبو بكر الصديق", "عمر بن الخطاب", "علي بن أبي طالب", "زيد بن حارثة"], "المراد ثاني اثنين في غار ثور، وقد اتفق المفسرون على أنه أبو بكر؛ أما علي فبقي في مكة ونام في فراش النبي ﷺ."] },
  // ---------- stage 2 ----------
  { id: "srm-021", s: "seerah", g: 2, d: 2, t: ["birth-and-childhood", "abd-al-muttalib"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the death of Āmina",
    en: ["Who took charge of the Prophet immediately after the death of his mother?", ["His grandfather ʿAbd al-Muṭṭalib", "His uncle Abū Ṭālib", "His uncle al-ʿAbbās", "His wet nurse Ḥalīma"], "After Āmina died, his grandfather ʿAbd al-Muṭṭalib took him in and treated him with special affection. Only after ʿAbd al-Muṭṭalib's death did Abū Ṭālib become his guardian."],
    de: ["Wer nahm den Propheten unmittelbar nach dem Tod seiner Mutter zu sich?", ["Sein Großvater ʿAbd al-Muṭṭalib", "Sein Onkel Abū Ṭālib", "Sein Onkel al-ʿAbbās", "Seine Amme Ḥalīma"], "Nach Āminas Tod nahm ihn sein Großvater ʿAbd al-Muṭṭalib auf und behandelte ihn mit besonderer Zuneigung. Erst nach dessen Tod wurde Abū Ṭālib sein Vormund."],
    ar: ["مَن كفل النبي ﷺ مباشرة بعد وفاة أمه؟", ["جده عبد المطلب", "عمه أبو طالب", "عمه العباس", "مرضعته حليمة"], "بعد وفاة آمنة كفله جده عبد المطلب وكان شديد العطف عليه، ولم تنتقل كفالته إلى أبي طالب إلا بعد موت عبد المطلب."] },
  { id: "srm-022", s: "seerah", g: 2, d: 2, t: ["birth-and-childhood"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the death of Āmina",
    en: ["Where did Āmina, the Prophet's mother, die?", ["At al-Abwāʾ, between Mecca and Yathrib", "In Mecca, in the house of ʿAbd al-Muṭṭalib", "In al-Ṭāʾif, among Banū Saʿd", "In Yathrib, among Banū al-Najjār"], "Returning from a visit to relatives of ʿAbd al-Muṭṭalib's mother in Yathrib, Āmina fell ill and died at al-Abwāʾ when the Prophet was about six years old."],
    de: ["Wo starb Āmina, die Mutter des Propheten?", ["In al-Abwāʾ, zwischen Mekka und Yathrib", "In Mekka, im Haus ʿAbd al-Muṭṭalibs", "In aṭ-Ṭāʾif, bei den Banū Saʿd", "In Yathrib, bei den Banū an-Naddschār"], "Auf dem Rückweg von einem Besuch bei Verwandten in Yathrib erkrankte Āmina und starb in al-Abwāʾ, als der Prophet etwa sechs Jahre alt war."],
    ar: ["أين توفيت آمنة أم النبي ﷺ؟", ["بالأبواء بين مكة ويثرب", "بمكة في بيت عبد المطلب", "بالطائف عند بني سعد", "بيثرب عند بني النجار"], "مرضت آمنة وهي راجعة من زيارة أخوال عبد المطلب بيثرب فتوفيت بالأبواء، وكان النبي ﷺ في نحو السادسة من عمره."] },
  { id: "srm-023", s: "seerah", g: 2, d: 3, t: ["birth-and-childhood"], src: "Ibn Saʿd, al-Ṭabaqāt al-Kubrā, account of Umm Ayman",
    en: ["Which woman accompanied Āmina and the young Muḥammad on the journey to Yathrib and brought him back to Mecca?", ["Umm Ayman (Baraka)", "Thuwayba", "Ḥalīma al-Saʿdiyya", "Ṣafiyya bint ʿAbd al-Muṭṭalib"], "Umm Ayman, the Abyssinian servant inherited from his father, was with them and brought the orphaned boy home after Āmina's death at al-Abwāʾ. He later honoured her as a second mother."],
    de: ["Welche Frau begleitete Āmina und den jungen Muḥammad nach Yathrib und brachte ihn nach Mekka zurück?", ["Umm Aiman (Baraka)", "Thuwaiba", "Ḥalīma as-Saʿdiyya", "Ṣafiyya bint ʿAbd al-Muṭṭalib"], "Umm Aiman, die abessinische Dienerin aus dem Erbe seines Vaters, war dabei und brachte den verwaisten Jungen nach Āminas Tod in al-Abwāʾ heim. Er ehrte sie später wie eine zweite Mutter."],
    ar: ["مَن المرأة التي رافقت آمنة ومحمدًا ﷺ في الرحلة إلى يثرب وعادت به إلى مكة؟", ["أم أيمن بركة", "ثويبة", "حليمة السعدية", "صفية بنت عبد المطلب"], "كانت أم أيمن الحبشية، التي ورثها عن أبيه، معهما، فرجعت بالصبي اليتيم إلى مكة بعد وفاة آمنة بالأبواء، وكان يكرمها بعد ذلك كأمّ له."] },
  { id: "srm-024", s: "seerah", g: 2, d: 2, t: ["halima", "birth-and-childhood"], src: "Ṣaḥīḥ Muslim, Kitāb al-Īmān, the Isrāʾ and the opening of the chest",
    en: ["Which event took place while the Prophet was a child among Banū Saʿd?", ["Jibrīl opened and cleansed his chest", "He met the monk Baḥīrā", "He received the first revelation", "He joined the pact of Ḥilf al-Fuḍūl"], "Anas reports in Ṣaḥīḥ Muslim that Jibrīl came to him while he was playing with other boys, opened his chest and washed his heart. Baḥīrā and Ḥilf al-Fuḍūl came later in his youth."],
    de: ["Welches Ereignis geschah, als der Prophet als Kind bei den Banū Saʿd lebte?", ["Dschibrīl öffnete und reinigte seine Brust", "Er begegnete dem Mönch Baḥīrā", "Er empfing die erste Offenbarung", "Er trat dem Bund Ḥilf al-Fuḍūl bei"], "Anas berichtet in Ṣaḥīḥ Muslim, dass Dschibrīl zu ihm kam, während er mit anderen Jungen spielte, seine Brust öffnete und sein Herz wusch. Baḥīrā und Ḥilf al-Fuḍūl folgten später in seiner Jugend."],
    ar: ["أي حدث وقع للنبي ﷺ وهو صغير في بني سعد؟", ["شقّ جبريل صدره وطهّره", "لقاؤه الراهب بحيرا", "نزول الوحي عليه أول مرة", "شهوده حلف الفضول"], "روى مسلم عن أنس أن جبريل أتاه وهو يلعب مع الغلمان فشقّ صدره وغسل قلبه؛ أما بحيرا وحلف الفضول فكانا في شبابه بعد ذلك."] },
  { id: "srm-025", s: "seerah", g: 2, d: 3, t: ["pre-islamic-arabia", "quraysh-trade"], src: "Ibn Kathīr, Tafsīr, on Sūrat Quraysh", v: "106:2",
    en: ["The verse shown mentions the winter and summer journeys of Quraysh. According to the exegetes, where did they lead?", ["Winter to Yemen, summer to Syria", "Winter to Syria, summer to Yemen", "Winter to Iraq, summer to Egypt", "Winter to Abyssinia, summer to Iraq"], "Ibn Kathīr and others explain that Quraysh travelled to warm Yemen in winter and to Syria in summer. Their security as guardians of the Sanctuary made these caravans possible."],
    de: ["Die gezeigte Āya erwähnt die Winter- und Sommerreise der Quraisch. Wohin führten sie nach den Exegeten?", ["Im Winter in den Jemen, im Sommer nach Syrien", "Im Winter nach Syrien, im Sommer in den Jemen", "Im Winter in den Irak, im Sommer nach Ägypten", "Im Winter nach Abessinien, im Sommer in den Irak"], "Ibn Kathīr und andere erklären, dass die Quraisch im Winter in den warmen Jemen und im Sommer nach Syrien reisten. Ihre Sicherheit als Hüter des Heiligtums machte diese Karawanen möglich."],
    ar: ["تذكر الآية المعروضة رحلتي الشتاء والصيف لقريش. إلى أين كانتا عند المفسرين؟", ["الشتاء إلى اليمن والصيف إلى الشام", "الشتاء إلى الشام والصيف إلى اليمن", "الشتاء إلى العراق والصيف إلى مصر", "الشتاء إلى الحبشة والصيف إلى العراق"], "ذكر ابن كثير وغيره أن قريشًا كانت ترحل في الشتاء إلى اليمن لدفئه وفي الصيف إلى الشام، وكان أمنهم بجوار البيت هو ما يسّر لهم هذه التجارة."] },
  { id: "srm-026", s: "seerah", g: 2, d: 2, t: ["pre-islamic-arabia", "idolatry"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the idols of the Arabs",
    en: ["Which idol was regarded as the chief idol of Quraysh at the Kaʿba?", ["Hubal", "al-Lāt", "al-ʿUzzā", "Manāt"], "Hubal stood at the Kaʿba and divining arrows were cast before it. al-Lāt was worshipped at al-Ṭāʾif, al-ʿUzzā at Nakhla and Manāt near Qudayd on the coast."],
    de: ["Welcher Götze galt als Hauptgötze der Quraisch an der Kaʿba?", ["Hubal", "al-Lāt", "al-ʿUzzā", "Manāt"], "Hubal stand an der Kaʿba, und vor ihm wurden Lospfeile geworfen. al-Lāt wurde in aṭ-Ṭāʾif verehrt, al-ʿUzzā in Nachla und Manāt bei Qudaid an der Küste."],
    ar: ["أي صنم كان كبير أصنام قريش عند الكعبة؟", ["هُبَل", "اللات", "العزى", "مناة"], "كان هبل عند الكعبة تُضرب عنده الأزلام؛ أما اللات فكانت بالطائف، والعزى بنخلة، ومناة عند قُدَيد على الساحل."] },
  { id: "srm-027", s: "seerah", g: 2, d: 3, t: ["bahira", "birth-and-childhood"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the story of Baḥīrā",
    en: ["What did the monk Baḥīrā advise Abū Ṭālib to do with his nephew?", ["Take him back home and guard him well", "Leave him with the monks to study scripture", "Take him on to Jerusalem to be blessed", "Present him to the governor of Syria"], "Having recognised the signs of prophethood, Baḥīrā warned that the boy could come to harm and urged Abū Ṭālib to return him quickly to Mecca. The journey is commonly placed when he was about twelve."],
    de: ["Was riet der Mönch Baḥīrā Abū Ṭālib in Bezug auf seinen Neffen?", ["Ihn nach Hause zu bringen und gut zu behüten", "Ihn bei den Mönchen zum Schriftstudium zu lassen", "Ihn nach Jerusalem zu bringen, um ihn segnen zu lassen", "Ihn dem Statthalter Syriens vorzustellen"], "Da Baḥīrā die Zeichen des Prophetentums erkannte, warnte er, dem Jungen könne Schaden widerfahren, und drängte Abū Ṭālib, ihn rasch nach Mekka zurückzubringen. Die Reise wird meist auf sein zwölftes Lebensjahr datiert."],
    ar: ["بماذا أشار الراهب بحيرا على أبي طالب في شأن ابن أخيه؟", ["أن يرجع به إلى بلده ويحفظه", "أن يتركه عند الرهبان ليتعلم الكتاب", "أن يمضي به إلى بيت المقدس ليُبارَك", "أن يعرضه على والي الشام"], "لما عرف بحيرا علامات النبوة حذّر من أن يصيبه أذى، وأشار على أبي طالب أن يسرع بردّه إلى مكة؛ وتُذكر الرحلة في المشهور وهو ابن نحو اثنتي عشرة سنة."] },
  { id: "srm-028", s: "seerah", g: 2, d: 3, t: ["hilf-al-fudul", "character-before-prophethood"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, Ḥilf al-Fuḍūl",
    en: ["What was the purpose of Ḥilf al-Fuḍūl, which the Prophet attended as a young man?", ["To defend anyone wronged in Mecca until justice was done", "To unite Quraysh against the army of Abraha", "To divide the offices of the Kaʿba among the clans", "To boycott the clan of Banū Hāshim"], "Several clans of Quraysh pledged to stand by any victim of injustice in Mecca, whether local or a stranger, until his right was restored. The boycott of Banū Hāshim came decades later."],
    de: ["Welchen Zweck hatte der Ḥilf al-Fuḍūl, an dem der Prophet als junger Mann teilnahm?", ["Jedem in Mekka Benachteiligten beizustehen, bis ihm Recht geschah", "Die Quraisch gegen das Heer Abrahas zu vereinen", "Die Ämter der Kaʿba unter den Clans aufzuteilen", "Den Clan der Banū Hāschim zu boykottieren"], "Mehrere Clans der Quraisch verpflichteten sich, jedem Opfer von Unrecht in Mekka beizustehen, ob Einheimischer oder Fremder, bis sein Recht wiederhergestellt war. Der Boykott der Banū Hāschim folgte Jahrzehnte später."],
    ar: ["ما مقصد حلف الفضول الذي شهده النبي ﷺ في شبابه؟", ["نصرة كل مظلوم بمكة حتى يُردّ إليه حقه", "توحيد قريش في وجه جيش أبرهة", "تقسيم مناصب الكعبة بين البطون", "مقاطعة بني هاشم"], "تعاهدت بطون من قريش على أن يكونوا مع كل مظلوم بمكة، من أهلها أو من غيرهم، حتى تُردّ مظلمته؛ أما مقاطعة بني هاشم فكانت بعد ذلك بعقود."] },
  { id: "srm-029", s: "seerah", g: 2, d: 2, t: ["khadija", "chronology"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, marriage to Khadīja",
    en: ["According to the commonly stated account, how old were the Prophet and Khadīja when they married?", ["He was 25 and she was 40", "He was 20 and she was 30", "He was 30 and she was 45", "He was 25 and she was 25"], "Most biographers state that he was twenty-five and she forty; some reports give her a younger age, so the figure is the common, not the only, view."],
    de: ["Wie alt waren der Prophet und Chadīdscha nach der verbreiteten Darstellung bei ihrer Heirat?", ["Er 25 und sie 40", "Er 20 und sie 30", "Er 30 und sie 45", "Er 25 und sie 25"], "Die meisten Biographen nennen für ihn fünfundzwanzig und für sie vierzig Jahre; einige Berichte geben ihr ein jüngeres Alter, die Angabe ist also die verbreitete, nicht die einzige."],
    ar: ["كم كان عمر النبي ﷺ وخديجة عند زواجهما على المشهور؟", ["هو ابن خمس وعشرين وهي بنت أربعين", "هو ابن عشرين وهي بنت ثلاثين", "هو ابن ثلاثين وهي بنت خمس وأربعين", "هو ابن خمس وعشرين وهي كذلك"], "المشهور عند أهل السير أنه كان ابن خمس وعشرين وهي بنت أربعين، وفي بعض الروايات أنها كانت أصغر، فهذا هو القول المشهور لا الوحيد."] },
  { id: "srm-030", s: "seerah", g: 2, d: 3, t: ["khadija", "character-before-prophethood"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, marriage to Khadīja",
    en: ["Which servant of Khadīja accompanied the Prophet on her trade journey to Syria and reported his conduct to her?", ["Maysara", "Zayd ibn Ḥāritha", "Bilāl ibn Rabāḥ", "Abū Rāfiʿ"], "Maysara travelled with him, saw his honesty and the success of the trade, and told Khadīja, which moved her to propose marriage. Zayd came into the household later as a gift to Khadīja."],
    de: ["Welcher Diener Chadīdschas begleitete den Propheten auf ihrer Handelsreise nach Syrien und berichtete ihr von seinem Verhalten?", ["Maisara", "Zaid ibn Ḥāritha", "Bilāl ibn Rabāḥ", "Abū Rāfiʿ"], "Maisara reiste mit ihm, sah seine Ehrlichkeit und den Erfolg des Handels und erzählte es Chadīdscha, die daraufhin die Ehe vorschlug. Zaid kam später als Geschenk an Chadīdscha in den Haushalt."],
    ar: ["أي غلام لخديجة رافق النبي ﷺ في تجارتها إلى الشام وأخبرها بسيرته؟", ["ميسرة", "زيد بن حارثة", "بلال بن رباح", "أبو رافع"], "خرج ميسرة معه فرأى أمانته وربح التجارة فأخبر خديجة، فرغبت في الزواج منه؛ أما زيد فدخل البيت بعد ذلك هبةً لخديجة."] },
  { id: "srm-031", s: "seerah", g: 2, d: 2, t: ["kaaba-rebuilding", "black-stone"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the rebuilding of the Kaʿba",
    en: ["How did the Prophet settle the dispute over who would set the Black Stone back in place?", ["He placed it on a cloak and had a leader of each clan lift it together", "He cast lots among the clans of Quraysh", "He set it in place alone without consulting anyone", "He gave the honour to the eldest man of Quraysh"], "He laid the stone on a cloak, let a representative of every clan hold an edge and raise it, then set it in place with his own hands, so that every clan shared the honour."],
    de: ["Wie schlichtete der Prophet den Streit darüber, wer den Schwarzen Stein wieder einsetzen sollte?", ["Er legte ihn auf ein Tuch und ließ es von je einem Clanführer gemeinsam anheben", "Er ließ unter den Clans der Quraisch das Los entscheiden", "Er setzte ihn allein ein, ohne jemanden zu fragen", "Er überließ die Ehre dem ältesten Mann der Quraisch"], "Er legte den Stein auf ein Tuch, ließ einen Vertreter jedes Clans eine Ecke fassen und anheben und setzte ihn dann eigenhändig ein, sodass alle Clans an der Ehre teilhatten."],
    ar: ["كيف فصل النبي ﷺ في النزاع على وضع الحجر الأسود؟", ["وضعه في ثوب وأمر سيد كل قبيلة أن يرفعوه معًا", "أقرع بين بطون قريش", "وضعه وحده دون مشاورة أحد", "جعل الشرف لأكبر رجال قريش سنًّا"], "بسط ثوبًا ووضع فيه الحجر وأمر من كل قبيلة رجلًا أن يأخذ بطرف منه فرفعوه، ثم وضعه بيده الشريفة، فاشترك الجميع في الشرف."] },
  { id: "srm-032", s: "seerah", g: 2, d: 3, t: ["first-revelation"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Badʾ al-Waḥy, hadith of ʿĀʾisha",
    en: ["According to ʿĀʾisha in Ṣaḥīḥ al-Bukhārī, how did revelation first begin for the Prophet?", ["With true dreams that came like the break of dawn", "With a voice calling him from the Kaʿba", "With a written scroll brought by an angel", "With a vision during a trade journey"], "ʿĀʾisha reports that it began with true dreams, each one coming true like daybreak; then seclusion was made dear to him and he retreated to Ḥirāʾ."],
    de: ["Wie begann nach ʿĀʾischa in Ṣaḥīḥ al-Buchārī die Offenbarung für den Propheten?", ["Mit wahren Träumen, die wie der Anbruch der Morgendämmerung eintrafen", "Mit einer Stimme, die ihn von der Kaʿba aus rief", "Mit einer Schriftrolle, die ein Engel brachte", "Mit einer Vision auf einer Handelsreise"], "ʿĀʾischa berichtet, dass es mit wahren Träumen begann, die jeweils wie das Morgenlicht eintrafen; dann wurde ihm die Zurückgezogenheit lieb, und er zog sich nach Ḥirāʾ zurück."],
    ar: ["بماذا بدأ الوحي للنبي ﷺ كما في حديث عائشة في صحيح البخاري؟", ["بالرؤيا الصادقة تأتي مثل فلق الصبح", "بصوت يناديه من عند الكعبة", "بصحيفة مكتوبة يحملها ملك", "برؤية في رحلة تجارية"], "أخبرت عائشة أن أول ما بُدئ به الرؤيا الصادقة، فكان لا يرى رؤيا إلا جاءت مثل فلق الصبح، ثم حُبّب إليه الخلاء فكان يخلو بغار حراء."] },
  { id: "srm-033", s: "seerah", g: 2, d: 2, t: ["first-revelation", "waraqa"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Badʾ al-Waḥy, hadith of ʿĀʾisha",
    en: ["Who was Waraqa ibn Nawfal, to whom Khadīja took the Prophet after the first revelation?", ["Her cousin, a Christian who knew the earlier scriptures", "Her brother, a merchant of Quraysh", "Her servant, who had travelled with the Prophet", "A soothsayer whom Quraysh consulted"], "Waraqa was the son of Khadīja's paternal uncle; he had become a Christian in the time before Islam, wrote from the Gospel and was by then old and blind."],
    de: ["Wer war Waraqa ibn Naufal, zu dem Chadīdscha den Propheten nach der ersten Offenbarung brachte?", ["Ihr Vetter, ein Christ, der die früheren Schriften kannte", "Ihr Bruder, ein Kaufmann der Quraisch", "Ihr Diener, der mit dem Propheten gereist war", "Ein Wahrsager, den die Quraisch befragten"], "Waraqa war der Sohn ihres Onkels väterlicherseits; er war in vorislamischer Zeit Christ geworden, schrieb aus dem Evangelium ab und war damals alt und erblindet."],
    ar: ["مَن ورقة بن نوفل الذي انطلقت خديجة بالنبي ﷺ إليه بعد أول الوحي؟", ["ابن عمّها، تنصّر وعرف الكتب السابقة", "أخوها، تاجر من قريش", "غلامها الذي سافر مع النبي ﷺ", "كاهن كانت قريش تستفتيه"], "ورقة ابن عم خديجة، تنصّر في الجاهلية وكان يكتب من الإنجيل، وكان حينئذ شيخًا كبيرًا قد عمي."] },
  { id: "srm-034", s: "seerah", g: 2, d: 3, t: ["first-revelation", "khadija"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Badʾ al-Waḥy, hadith of ʿĀʾisha",
    en: ["When the Prophet came home frightened from Ḥirāʾ, which quality of his did Khadīja mention to reassure him?", ["That he kept the ties of kinship", "That he led the caravans of Quraysh", "That he was the finest poet of Mecca", "That he owned great wealth from trade"], "Khadīja said God would never disgrace him, because he kept ties of kinship, bore the burden of the weak, helped the destitute, honoured guests and supported people in true hardship."],
    de: ["Als der Prophet verängstigt aus Ḥirāʾ heimkam, welche seiner Eigenschaften nannte Chadīdscha, um ihn zu beruhigen?", ["Dass er die Verwandtschaftsbande pflegte", "Dass er die Karawanen der Quraisch anführte", "Dass er der beste Dichter Mekkas war", "Dass er großen Reichtum aus dem Handel besaß"], "Chadīdscha sagte, Gott werde ihn niemals erniedrigen, denn er pflege die Verwandtschaftsbande, trage die Last der Schwachen, helfe den Mittellosen, ehre Gäste und stehe Menschen in echter Not bei."],
    ar: ["لما رجع النبي ﷺ من حراء خائفًا، أيّ صفاته ذكرت خديجة لتطمئنه؟", ["أنه يصل الرحم", "أنه يقود قوافل قريش", "أنه أشعر أهل مكة", "أنه ذو مال كثير من التجارة"], "قالت خديجة إن الله لا يخزيه أبدًا، لأنه يصل الرحم ويحمل الكلّ ويُكسب المعدوم ويقري الضيف ويعين على نوائب الحق."] },
  { id: "srm-035", s: "seerah", g: 2, d: 2, t: ["early-muslims"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the first to accept Islam",
    en: ["Who is counted as the first boy to accept Islam?", ["ʿAlī ibn Abī Ṭālib", "Zayd ibn Ḥāritha", "ʿAbdullāh ibn ʿAbbās", "Usāma ibn Zayd"], "ʿAlī was living in the Prophet's household as a child and believed early on. Ibn ʿAbbās and Usāma were born later, around or after the Hijra period."],
    de: ["Wer gilt als erster Junge, der den Islam annahm?", ["ʿAlī ibn Abī Ṭālib", "Zaid ibn Ḥāritha", "ʿAbdullāh ibn ʿAbbās", "Usāma ibn Zaid"], "ʿAlī lebte als Kind im Haushalt des Propheten und glaubte sehr früh. Ibn ʿAbbās und Usāma wurden erst später geboren."],
    ar: ["مَن أول من أسلم من الصبيان؟", ["علي بن أبي طالب", "زيد بن حارثة", "عبد الله بن عباس", "أسامة بن زيد"], "كان علي يعيش صغيرًا في بيت النبي ﷺ فآمن مبكرًا؛ أما ابن عباس وأسامة فوُلدا بعد ذلك بزمن."] },
  { id: "srm-036", s: "seerah", g: 2, d: 3, t: ["early-muslims", "secret-call"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the secret phase of the call",
    en: ["Which house near al-Ṣafā served as a meeting place for the early Muslims during the secret phase?", ["Dār al-Arqam", "Dār al-Nadwa", "The house of Abū Sufyān", "The house of ʿAbdullāh ibn Judʿān"], "The Prophet met his followers to teach them in the house of al-Arqam ibn Abī al-Arqam. Dār al-Nadwa was the council house of Quraysh where the Hijra plot was later hatched."],
    de: ["Welches Haus bei aṣ-Ṣafā diente den frühen Muslimen in der geheimen Phase als Treffpunkt?", ["Dār al-Arqam", "Dār an-Nadwa", "Das Haus Abū Sufyāns", "Das Haus ʿAbdullāh ibn Dschudʿāns"], "Der Prophet unterrichtete seine Anhänger im Haus von al-Arqam ibn Abī al-Arqam. Dār an-Nadwa war das Ratshaus der Quraisch, in dem später der Anschlag vor der Hidschra geplant wurde."],
    ar: ["أي دار قرب الصفا كانت مجمعًا للمسلمين الأوائل في مرحلة الدعوة السرية؟", ["دار الأرقم", "دار الندوة", "دار أبي سفيان", "دار عبد الله بن جدعان"], "كان النبي ﷺ يجتمع بأصحابه ويعلّمهم في دار الأرقم بن أبي الأرقم؛ أما دار الندوة فمجلس شورى قريش الذي دُبّرت فيه المؤامرة قبل الهجرة."] },
  { id: "srm-037", s: "seerah", g: 2, d: 2, t: ["public-call"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Tafsīr, Sūrat al-Shuʿarāʾ", v: "26:214",
    en: ["After the verse shown was revealed, where did the Prophet stand to call the clans of Quraysh?", ["On the hill of al-Ṣafā", "On the mountain of Ḥirāʾ", "At the hill of al-Marwa", "At the plain of ʿArafa"], "The verse commanded him to warn his nearest kinsfolk; he climbed al-Ṣafā and called the clans by name, asking whether they would believe him if he warned of an army behind the hill (al-Bukhārī)."],
    de: ["Wo stellte sich der Prophet nach der Offenbarung der gezeigten Āya hin, um die Clans der Quraisch zu rufen?", ["Auf den Hügel aṣ-Ṣafā", "Auf den Berg Ḥirāʾ", "Auf den Hügel al-Marwa", "In die Ebene von ʿArafa"], "Die Āya befahl ihm, seine nächsten Verwandten zu warnen; er stieg auf aṣ-Ṣafā, rief die Clans beim Namen und fragte, ob sie ihm glauben würden, wenn er vor einem Heer hinter dem Hügel warnte (al-Buchārī)."],
    ar: ["بعد نزول الآية المعروضة، أين وقف النبي ﷺ ينادي بطون قريش؟", ["على جبل الصفا", "على جبل حراء", "على المروة", "بصعيد عرفة"], "أُمر في الآية بإنذار عشيرته الأقربين، فصعد الصفا ونادى البطون بأسمائها وسألهم: أتصدقونني لو أخبرتكم أن خيلًا وراء هذا الوادي، كما في البخاري."] },
  { id: "srm-038", s: "seerah", g: 2, d: 2, t: ["persecution", "family-of-yasir"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the persecution of the weak Muslims",
    en: ["Who is known as the first martyr in Islam?", ["Sumayya bint Khayyāṭ, mother of ʿAmmār", "Bilāl ibn Rabāḥ", "Ḥamza ibn ʿAbd al-Muṭṭalib", "Muṣʿab ibn ʿUmayr"], "Sumayya, wife of Yāsir and mother of ʿAmmār, was killed in Mecca for refusing to renounce Islam. Bilāl survived his torture; Ḥamza and Muṣʿab fell later at Uḥud."],
    de: ["Wer gilt als erste Märtyrerin bzw. erster Märtyrer des Islam?", ["Sumayya bint Chayyāṭ, die Mutter ʿAmmārs", "Bilāl ibn Rabāḥ", "Ḥamza ibn ʿAbd al-Muṭṭalib", "Muṣʿab ibn ʿUmair"], "Sumayya, die Frau Yāsirs und Mutter ʿAmmārs, wurde in Mekka getötet, weil sie dem Islam nicht abschwor. Bilāl überlebte die Folter; Ḥamza und Muṣʿab fielen später bei Uḥud."],
    ar: ["مَن أول شهيد في الإسلام؟", ["سمية بنت خياط أم عمار", "بلال بن رباح", "حمزة بن عبد المطلب", "مصعب بن عمير"], "قُتلت سمية زوج ياسر وأم عمار بمكة لثباتها على الإسلام؛ أما بلال فنجا من العذاب، واستُشهد حمزة ومصعب بعد ذلك في أحد."] },
  { id: "srm-039", s: "seerah", g: 2, d: 3, t: ["abyssinia", "jafar"], src: "Musnad Aḥmad, hadith of Umm Salama on the emigration to Abyssinia",
    en: ["Who spoke on behalf of the Muslim emigrants before al-Najāshī?", ["Jaʿfar ibn Abī Ṭālib", "ʿUthmān ibn ʿAffān", "ʿAbdullāh ibn Masʿūd", "Muṣʿab ibn ʿUmayr"], "In the report of Umm Salama, the emigrants chose Jaʿfar to answer the king; he described their former ignorance, the message of the Prophet and the persecution they suffered."],
    de: ["Wer sprach vor an-Nadschāschī im Namen der muslimischen Auswanderer?", ["Dschaʿfar ibn Abī Ṭālib", "ʿUthmān ibn ʿAffān", "ʿAbdullāh ibn Masʿūd", "Muṣʿab ibn ʿUmair"], "Im Bericht Umm Salamas wählten die Auswanderer Dschaʿfar, um dem König zu antworten; er schilderte ihre frühere Unwissenheit, die Botschaft des Propheten und die erlittene Verfolgung."],
    ar: ["مَن تكلّم باسم المهاجرين المسلمين بين يدي النجاشي؟", ["جعفر بن أبي طالب", "عثمان بن عفان", "عبد الله بن مسعود", "مصعب بن عمير"], "في رواية أم سلمة اختار المهاجرون جعفرًا ليجيب الملك، فوصف ما كانوا عليه في الجاهلية وما جاء به النبي ﷺ وما لقوه من الأذى."] },
  { id: "srm-040", s: "seerah", g: 2, d: 2, t: ["boycott"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the boycott document",
    en: ["Where were Banū Hāshim confined during the boycott imposed by Quraysh?", ["In Shiʿb Abī Ṭālib", "In Dār al-Arqam", "In the valley of Minā", "In the town of al-Ṭāʾif"], "Quraysh agreed not to marry, trade or deal with Banū Hāshim and Banū al-Muṭṭalib, who withdrew into the ravine of Abū Ṭālib in Mecca and suffered great hunger there."],
    de: ["Wo mussten die Banū Hāschim während des von den Quraisch verhängten Boykotts ausharren?", ["Im Schiʿb Abī Ṭālib", "In Dār al-Arqam", "Im Tal von Minā", "In der Stadt aṭ-Ṭāʾif"], "Die Quraisch beschlossen, mit den Banū Hāschim und Banū al-Muṭṭalib weder zu heiraten noch zu handeln; diese zogen sich in die Schlucht Abū Ṭālibs in Mekka zurück und litten dort großen Hunger."],
    ar: ["أين حوصر بنو هاشم في أثناء المقاطعة التي فرضتها قريش؟", ["في شِعب أبي طالب", "في دار الأرقم", "في وادي منى", "في الطائف"], "تعاهدت قريش على ألا تناكح بني هاشم وبني المطلب ولا تبايعهم، فانحازوا إلى شعب أبي طالب بمكة ولقوا فيه جوعًا شديدًا."] },
  { id: "srm-041", s: "seerah", g: 2, d: 2, t: ["taif"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the journey to al-Ṭāʾif",
    en: ["Who accompanied the Prophet on his journey to al-Ṭāʾif?", ["Zayd ibn Ḥāritha", "Abū Bakr al-Ṣiddīq", "ʿAlī ibn Abī Ṭālib", "Bilāl ibn Rabāḥ"], "Most biographers name Zayd ibn Ḥāritha, his freedman and adopted son, who shielded him from the stones thrown by the people of al-Ṭāʾif."],
    de: ["Wer begleitete den Propheten auf seiner Reise nach aṭ-Ṭāʾif?", ["Zaid ibn Ḥāritha", "Abū Bakr aṣ-Ṣiddīq", "ʿAlī ibn Abī Ṭālib", "Bilāl ibn Rabāḥ"], "Die meisten Biographen nennen Zaid ibn Ḥāritha, seinen Freigelassenen und Adoptivsohn, der ihn vor den Steinen der Leute von aṭ-Ṭāʾif schützte."],
    ar: ["مَن رافق النبي ﷺ في رحلته إلى الطائف؟", ["زيد بن حارثة", "أبو بكر الصديق", "علي بن أبي طالب", "بلال بن رباح"], "يذكر أكثر أهل السير أنه زيد بن حارثة مولاه ومتبنّاه، وكان يقيه بنفسه الحجارة التي رماه بها أهل الطائف."] },
  { id: "srm-042", s: "seerah", g: 2, d: 2, t: ["isra-miraj", "salah"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Ṣalāt, how prayer was prescribed on the Night Journey",
    en: ["What was prescribed for the Muslims during the Miʿrāj?", ["The five daily prayers", "The fast of Ramaḍān", "The obligatory zakāt", "The pilgrimage to Mecca"], "The prayers were first prescribed as fifty and reduced, at the Prophet's repeated request, to five, keeping the reward of fifty (al-Bukhārī). Fasting, zakāt and ḥajj were prescribed later in Medina."],
    de: ["Was wurde den Muslimen während des Miʿrādsch vorgeschrieben?", ["Die fünf täglichen Gebete", "Das Fasten im Ramaḍān", "Die Pflichtabgabe Zakāt", "Die Pilgerfahrt nach Mekka"], "Die Gebete wurden zunächst als fünfzig vorgeschrieben und auf wiederholte Bitte des Propheten auf fünf verringert, mit dem Lohn von fünfzig (al-Buchārī). Fasten, Zakāt und Ḥaddsch wurden später in Medina vorgeschrieben."],
    ar: ["ماذا فُرض على المسلمين في المعراج؟", ["الصلوات الخمس", "صوم رمضان", "الزكاة المفروضة", "حج البيت"], "فُرضت الصلاة خمسين ثم خُففت بمراجعة النبي ﷺ إلى خمس بأجر خمسين، كما في البخاري؛ أما الصوم والزكاة والحج ففُرضت بعد ذلك في المدينة."] },
  { id: "srm-043", s: "seerah", g: 2, d: 3, t: ["aqaba"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the first pledge of al-ʿAqaba",
    en: ["How many men from Yathrib took the first pledge of al-ʿAqaba?", ["Twelve", "Six", "Forty", "Seventy-three"], "The year before, six men of Khazraj had accepted Islam; the following season twelve men took the first pledge. About seventy-three men and two women came to the second pledge."],
    de: ["Wie viele Männer aus Yathrib leisteten den ersten Treueid von al-ʿAqaba?", ["Zwölf", "Sechs", "Vierzig", "Dreiundsiebzig"], "Im Jahr zuvor hatten sechs Männer der Chazradsch den Islam angenommen; in der folgenden Saison leisteten zwölf Männer den ersten Eid. Zum zweiten Eid kamen etwa dreiundsiebzig Männer und zwei Frauen."],
    ar: ["كم كان عدد رجال يثرب في بيعة العقبة الأولى؟", ["اثنا عشر رجلًا", "ستة رجال", "أربعون رجلًا", "ثلاثة وسبعون رجلًا"], "أسلم قبلها بعام ستة نفر من الخزرج، ثم بايع في الموسم التالي اثنا عشر رجلًا البيعة الأولى، وحضر البيعة الثانية نحو ثلاثة وسبعين رجلًا وامرأتين."] },
  { id: "srm-044", s: "seerah", g: 2, d: 3, t: ["hijra", "suraqa"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Manāqib al-Anṣār, the Hijra of the Prophet",
    en: ["What happened to Surāqa ibn Mālik when he pursued the Prophet during the Hijra?", ["His horse's legs sank into the ground", "He was captured by Banū Aslam", "He lost the trail in the cave of Thawr", "His horse threw him into a well"], "Surāqa set out for the reward Quraysh had offered; as he drew near, his horse's forelegs sank into the ground more than once, and he asked for a written assurance of safety and turned back (al-Bukhārī)."],
    de: ["Was geschah mit Surāqa ibn Mālik, als er den Propheten während der Hidschra verfolgte?", ["Die Beine seines Pferdes versanken im Boden", "Er wurde von den Banū Aslam gefangen genommen", "Er verlor die Spur an der Höhle Thaur", "Sein Pferd warf ihn in einen Brunnen"], "Surāqa zog wegen der von den Quraisch ausgesetzten Belohnung los; als er näherkam, versanken die Vorderbeine seines Pferdes mehrmals im Boden, worauf er um eine schriftliche Sicherheitszusage bat und umkehrte (al-Buchārī)."],
    ar: ["ماذا حدث لسراقة بن مالك حين لحق بالنبي ﷺ في الهجرة؟", ["ساخت قوائم فرسه في الأرض", "أسرته بنو أسلم", "أضاع الأثر عند غار ثور", "ألقاه فرسه في بئر"], "خرج سراقة طمعًا في الجُعل الذي جعلته قريش، فلما دنا ساخت يدا فرسه في الأرض مرة بعد مرة، فطلب كتاب أمان ورجع، كما في البخاري."] },
  // ---------- stage 3 ----------
  { id: "srm-045", s: "seerah", g: 3, d: 3, t: ["year-of-elephant", "pre-islamic-arabia"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the affair of the Elephant",
    en: ["In whose name did Abraha govern Yemen when he marched on Mecca?", ["The Christian king of Abyssinia (Aksum)", "The Persian emperor", "The Byzantine emperor directly", "The native Ḥimyarite kings"], "Abraha was an Abyssinian commander ruling Yemen as viceroy of the Negus after Aksum had conquered the Ḥimyarite kingdom. Persia took Yemen only some years later."],
    de: ["In wessen Namen regierte Abraha den Jemen, als er gegen Mekka zog?", ["Im Namen des christlichen Königs von Abessinien (Aksum)", "Im Namen des persischen Großkönigs", "Unmittelbar im Namen des byzantinischen Kaisers", "Im Namen der einheimischen ḥimyaritischen Könige"], "Abraha war ein abessinischer Feldherr, der den Jemen als Statthalter des Negus regierte, nachdem Aksum das Reich der Ḥimyar erobert hatte. Persien übernahm den Jemen erst einige Jahre später."],
    ar: ["باسم مَن كان أبرهة يحكم اليمن حين سار إلى مكة؟", ["ملك الحبشة النصراني", "كسرى ملك فارس", "قيصر الروم مباشرة", "ملوك حمير من أهل اليمن"], "كان أبرهة قائدًا حبشيًّا يحكم اليمن نائبًا عن النجاشي بعد أن غلبت الحبشة على ملك حمير؛ ولم تستولِ فارس على اليمن إلا بعد ذلك بسنوات."] },
  { id: "srm-046", s: "seerah", g: 3, d: 3, t: ["abd-al-muttalib", "pre-islamic-arabia"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the digging of Zamzam",
    en: ["For which deed is ʿAbd al-Muṭṭalib especially remembered in the history of Mecca?", ["He rediscovered and re-dug the well of Zamzam", "He founded the council house Dār al-Nadwa", "He introduced the two seasonal caravan journeys", "He was the first to place a covering on the Kaʿba"], "Guided by a dream, ʿAbd al-Muṭṭalib located and re-dug the long-buried well of Zamzam. Dār al-Nadwa is attributed to Quṣayy and the caravan journeys to Hāshim."],
    de: ["Für welche Tat ist ʿAbd al-Muṭṭalib in der Geschichte Mekkas besonders bekannt?", ["Er fand den Brunnen Zamzam wieder und grub ihn neu aus", "Er gründete das Ratshaus Dār an-Nadwa", "Er führte die beiden jahreszeitlichen Karawanenreisen ein", "Er bedeckte als Erster die Kaʿba mit einem Tuch"], "Durch einen Traum geleitet, fand ʿAbd al-Muṭṭalib den lange verschütteten Brunnen Zamzam und grub ihn wieder aus. Dār an-Nadwa wird Quṣayy zugeschrieben, die Karawanenreisen Hāschim."],
    ar: ["بأي عمل يُذكر عبد المطلب خاصة في تاريخ مكة؟", ["أنه اهتدى إلى بئر زمزم وأعاد حفرها", "أنه بنى دار الندوة", "أنه سنّ رحلتي الشتاء والصيف", "أنه أول من كسا الكعبة"], "رأى عبد المطلب في منامه ما دلّه على موضع زمزم بعد أن طُمرت زمنًا طويلًا فحفرها؛ أما دار الندوة فتُنسب إلى قصي، والرحلتان إلى هاشم."] },
  { id: "srm-047", s: "seerah", g: 3, d: 4, t: ["birth-and-childhood", "halima"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Nikāḥ, foster relations through nursing",
    en: ["Before Ḥalīma, which woman briefly nursed the infant Prophet?", ["Thuwayba, a freedwoman of Abū Lahab", "Umm Ayman, his father's servant", "Fāṭima bint Asad, wife of Abū Ṭālib", "Ṣafiyya, his paternal aunt"], "Thuwayba nursed him for a short time; she had also nursed Ḥamza and Abū Salama, which made them his foster brothers (al-Bukhārī). Umm Ayman cared for him but did not nurse him."],
    de: ["Welche Frau stillte den Propheten als Säugling kurz vor Ḥalīma?", ["Thuwaiba, eine Freigelassene Abū Lahabs", "Umm Aiman, die Dienerin seines Vaters", "Fāṭima bint Asad, die Frau Abū Ṭālibs", "Ṣafiyya, seine Tante väterlicherseits"], "Thuwaiba stillte ihn eine kurze Zeit; sie hatte auch Ḥamza und Abū Salama gestillt, die dadurch seine Milchbrüder wurden (al-Buchārī). Umm Aiman versorgte ihn, stillte ihn aber nicht."],
    ar: ["مَن المرأة التي أرضعت النبي ﷺ مدة يسيرة قبل حليمة؟", ["ثويبة مولاة أبي لهب", "أم أيمن حاضنته", "فاطمة بنت أسد زوج أبي طالب", "صفية عمّته"], "أرضعته ثويبة أيامًا، وكانت قد أرضعت حمزة وأبا سلمة فصارا أخويه من الرضاعة، كما في البخاري؛ أما أم أيمن فكانت حاضنته ولم ترضعه."] },
  { id: "srm-048", s: "seerah", g: 3, d: 3, t: ["khadija", "prophets-household"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the children of the Prophet",
    en: ["Which of the Prophet's children was NOT born to Khadīja?", ["Ibrāhīm", "Fāṭima", "Zaynab", "al-Qāsim"], "All his children were from Khadīja except Ibrāhīm, who was born to Māriya in Medina and died in infancy. al-Qāsim, after whom he was called Abū al-Qāsim, was Khadīja's son."],
    de: ["Welches Kind des Propheten stammte NICHT von Chadīdscha?", ["Ibrāhīm", "Fāṭima", "Zainab", "al-Qāsim"], "Alle seine Kinder stammten von Chadīdscha außer Ibrāhīm, den Māriya in Medina gebar und der als Kleinkind starb. al-Qāsim, nach dem er Abū l-Qāsim genannt wurde, war Chadīdschas Sohn."],
    ar: ["أيّ أولاد النبي ﷺ لم يكن من خديجة؟", ["إبراهيم", "فاطمة", "زينب", "القاسم"], "كل أولاده من خديجة إلا إبراهيم، فأمه مارية، وُلد بالمدينة ومات صغيرًا؛ أما القاسم الذي كُني به أبا القاسم فابن خديجة."] },
  { id: "srm-049", s: "seerah", g: 3, d: 4, t: ["kaaba-rebuilding"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Ḥajj, the virtue of Mecca and its building",
    en: ["Why did Quraysh leave part of the original Kaʿba (the Ḥijr) outside the walls when they rebuilt it?", ["Their lawful funds were not enough to complete it", "The ground there was too rocky to build on", "An idol stood there that they would not move", "Abraha's army had destroyed that part beyond repair"], "ʿĀʾisha reports that the Prophet told her Quraysh ran short of means (al-Bukhārī); the biographers add that they had resolved to use only wealth of good origin. So the semicircular Ḥijr remained outside."],
    de: ["Warum ließen die Quraisch beim Neubau einen Teil der ursprünglichen Kaʿba (den Ḥidschr) außerhalb der Mauern?", ["Ihre rechtmäßigen Mittel reichten nicht für den vollständigen Bau", "Der Boden dort war zu felsig", "Dort stand ein Götze, den sie nicht entfernen wollten", "Abrahas Heer hatte diesen Teil unwiederbringlich zerstört"], "ʿĀʾischa berichtet, der Prophet habe ihr gesagt, den Quraisch hätten die Mittel gefehlt (al-Buchārī); die Biographen ergänzen, sie hätten nur Vermögen guter Herkunft verwenden wollen. So blieb der halbrunde Ḥidschr draußen."],
    ar: ["لماذا تركت قريش جزءًا من الكعبة الأصلية (الحِجر) خارج البناء حين أعادت بناءها؟", ["لأن النفقة الطيبة قصرت بهم", "لأن الأرض هناك صخرية لا يُبنى عليها", "لأن صنمًا كان هناك فأبوا نقله", "لأن جيش أبرهة هدم ذلك الجزء"], "روت عائشة أن النبي ﷺ أخبرها أن قريشًا قصرت بهم النفقة، كما في البخاري، وذكر أهل السير أنهم تعاهدوا ألا يُدخلوا فيها إلا مالًا طيبًا، فبقي الحِجر خارجها."] },
  { id: "srm-050", s: "seerah", g: 3, d: 3, t: ["first-revelation", "waraqa"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Badʾ al-Waḥy, hadith of ʿĀʾisha",
    en: ["How did Waraqa ibn Nawfal identify the being who had come to the Prophet in Ḥirāʾ?", ["As the same Nāmūs (angel of revelation) sent to Mūsā", "As a jinn of the kind that inspires poets", "As the spirit of an earlier king of Mecca", "As a vision caused by long fasting"], "Waraqa said it was the Nāmūs that God had sent down to Moses, i.e. Jibrīl, the bearer of revelation. Quraysh later accused the Prophet of being a poet or possessed, which Waraqa's answer contradicts."],
    de: ["Wie deutete Waraqa ibn Naufal das Wesen, das in Ḥirāʾ zum Propheten gekommen war?", ["Als denselben Nāmūs (Engel der Offenbarung), der zu Mūsā gesandt wurde", "Als einen Dschinn, wie er Dichter inspiriert", "Als den Geist eines früheren Königs von Mekka", "Als eine Vision infolge langen Fastens"], "Waraqa sagte, es sei der Nāmūs, den Gott zu Mose herabgesandt habe, also Dschibrīl, der Überbringer der Offenbarung. Die Quraisch warfen dem Propheten später vor, Dichter oder besessen zu sein, was Waraqas Antwort widerspricht."],
    ar: ["بماذا وصف ورقة بن نوفل الذي جاء النبي ﷺ في حراء؟", ["بأنه الناموس الذي أُنزل على موسى", "بأنه جنّيّ من الذين يُلهمون الشعراء", "بأنه روح ملك قديم من ملوك مكة", "بأنه خيال من أثر طول الصيام"], "قال ورقة إنه الناموس الذي نزّل الله على موسى، أي جبريل صاحب الوحي؛ وهذا يردّ ما رمته به قريش بعدُ من الشعر والجنون."] },
  { id: "srm-051", s: "seerah", g: 3, d: 4, t: ["first-revelation", "pause-in-revelation"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Tafsīr, Sūrat al-Muddaththir, hadith of Jābir", v: "74:1",
    en: ["According to the hadith of Jābir in Ṣaḥīḥ al-Bukhārī, when was the passage beginning with the verse shown revealed?", ["After a pause in revelation that followed the events of Ḥirāʾ", "On the night of al-Isrāʾ wa-l-Miʿrāj", "During the boycott in Shiʿb Abī Ṭālib", "On the night of the second pledge of al-ʿAqaba"], "Jābir reports that the Prophet saw the angel of Ḥirāʾ again between heaven and earth after the revelation had paused, and then the opening of al-Muddaththir came down. The majority hold that al-ʿAlaq preceded it."],
    de: ["Wann wurde der mit der gezeigten Āya beginnende Abschnitt nach dem Ḥadīth Dschābirs in Ṣaḥīḥ al-Buchārī offenbart?", ["Nach einer Pause der Offenbarung, die auf die Ereignisse von Ḥirāʾ folgte", "In der Nacht von al-Isrāʾ wa-l-Miʿrādsch", "Während des Boykotts im Schiʿb Abī Ṭālib", "In der Nacht des zweiten Eides von al-ʿAqaba"], "Dschābir berichtet, der Prophet habe den Engel von Ḥirāʾ nach einer Unterbrechung der Offenbarung zwischen Himmel und Erde wiedergesehen; dann kam der Anfang von al-Muddaththir herab. Die Mehrheit hält al-ʿAlaq für früher."],
    ar: ["متى نزل المقطع الذي يبدأ بالآية المعروضة بحسب حديث جابر في صحيح البخاري؟", ["بعد فترة الوحي التي أعقبت أحداث حراء", "ليلة الإسراء والمعراج", "في أثناء الحصار في شعب أبي طالب", "ليلة بيعة العقبة الثانية"], "روى جابر أن النبي ﷺ رأى الملك الذي جاءه بحراء بين السماء والأرض بعد فترة الوحي، فنزل صدر سورة المدثر؛ والجمهور على أن صدر سورة العلق نزل قبلها."] },
  { id: "srm-052", s: "seerah", g: 3, d: 4, t: ["pause-in-revelation", "opposition-of-quraysh"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Tafsīr, Sūrat al-Ḍuḥā, hadith of Jundub", v: "93:3",
    en: ["The verse shown reassured the Prophet. According to the report of Jundub in al-Bukhārī, what was the occasion?", ["A delay in revelation, after which a woman taunted that he had been abandoned", "His rejection by the leaders of al-Ṭāʾif", "The death of his uncle Abū Ṭālib", "The hunger of the boycott in Shiʿb Abī Ṭālib"], "Jundub reports that when the Prophet did not rise for prayer for a night or two and revelation was delayed, a woman of Quraysh mocked that his companion had left him; Sūrat al-Ḍuḥā then came down."],
    de: ["Die gezeigte Āya beruhigte den Propheten. Was war nach dem Bericht Dschundubs bei al-Buchārī der Anlass?", ["Eine Verzögerung der Offenbarung, nach der eine Frau spottete, er sei verlassen worden", "Seine Zurückweisung durch die Oberhäupter von aṭ-Ṭāʾif", "Der Tod seines Onkels Abū Ṭālib", "Der Hunger während des Boykotts im Schiʿb Abī Ṭālib"], "Dschundub berichtet: Als der Prophet eine oder zwei Nächte nicht zum Gebet aufstand und die Offenbarung ausblieb, spottete eine Frau der Quraisch, sein Gefährte habe ihn verlassen; daraufhin kam die Sure aḍ-Ḍuḥā herab."],
    ar: ["طمأنت الآية المعروضة النبيَّ ﷺ. ما سبب نزولها بحسب رواية جندب في البخاري؟", ["تأخُّر الوحي حتى زعمت امرأة أنه قد تُرك", "ردّ أشراف الطائف له", "موت عمه أبي طالب", "جوع الحصار في شعب أبي طالب"], "روى جندب أن النبي ﷺ لم يقم ليلة أو ليلتين وأبطأ عليه الوحي، فقالت امرأة من قريش إن صاحبه قد تركه، فنزلت سورة الضحى."] },
  { id: "srm-053", s: "seerah", g: 3, d: 4, t: ["public-call", "secret-call"], src: "Ibn Kathīr, Tafsīr, on 15:94; Ibn Hishām, al-Sīra al-Nabawiyya, the open call", v: "15:94",
    en: ["In the sīra literature, the verse shown is commonly cited as marking which turning point?", ["The move from secret to open preaching", "The permission to fight back", "The change of the qibla", "The order to emigrate to Abyssinia"], "Ibn Isḥāq and the exegetes link the verse to the end of the roughly three-year secret phase, when the Prophet was commanded to proclaim the message openly. Fighting and the qibla change belong to the Medinan period."],
    de: ["Als welcher Wendepunkt wird die gezeigte Āya in der Sīra-Literatur gewöhnlich angeführt?", ["Der Übergang von der geheimen zur offenen Verkündigung", "Die Erlaubnis, sich mit Waffen zu wehren", "Der Wechsel der Gebetsrichtung", "Der Befehl zur Auswanderung nach Abessinien"], "Ibn Isḥāq und die Exegeten verbinden die Āya mit dem Ende der etwa dreijährigen geheimen Phase, als der Prophet befohlen wurde, die Botschaft offen zu verkünden. Kampf und Qibla-Wechsel gehören in die medinensische Zeit."],
    ar: ["بأي منعطف تربط كتب السيرة الآية المعروضة في الغالب؟", ["الانتقال من الدعوة السرية إلى الجهر بها", "الإذن بالقتال", "تحويل القبلة", "الأمر بالهجرة إلى الحبشة"], "يربط ابن إسحاق والمفسرون الآية بنهاية المرحلة السرية التي دامت نحو ثلاث سنين، حين أُمر النبي ﷺ بالصدع بالدعوة؛ أما القتال وتحويل القبلة فمن العهد المدني."] },
  { id: "srm-054", s: "seerah", g: 3, d: 4, t: ["persecution", "family-of-yasir"], src: "Ibn Kathīr, Tafsīr, on 16:106; al-Wāḥidī, Asbāb al-Nuzūl", v: "16:106",
    en: ["The verse shown excuses one who is coerced into words of disbelief while his heart is firm in faith. Which Companion do the exegetes name as its occasion?", ["ʿAmmār ibn Yāsir", "Bilāl ibn Rabāḥ", "Khabbāb ibn al-Aratt", "Ṣuhayb al-Rūmī"], "Under torture after his parents were killed, ʿAmmār said what his tormentors demanded and came to the Prophet in distress; he was reassured, and the exegetes cite this verse in connection with him."],
    de: ["Die gezeigte Āya entschuldigt den, der zu Worten des Unglaubens gezwungen wird, während sein Herz im Glauben fest ist. Welchen Gefährten nennen die Exegeten als Anlass?", ["ʿAmmār ibn Yāsir", "Bilāl ibn Rabāḥ", "Chabbāb ibn al-Aratt", "Ṣuhaib ar-Rūmī"], "Unter Folter, nachdem seine Eltern getötet worden waren, sagte ʿAmmār, was seine Peiniger verlangten, und kam bestürzt zum Propheten; er wurde beruhigt, und die Exegeten führen diese Āya in Verbindung mit ihm an."],
    ar: ["تعذر الآية المعروضة من أُكره على كلمة الكفر وقلبه مطمئن بالإيمان. مَن الصحابي الذي يذكره المفسرون سببًا لنزولها؟", ["عمار بن ياسر", "بلال بن رباح", "خباب بن الأرت", "صهيب الرومي"], "عُذّب عمار بعد قتل أبويه فقال ما أرادوا، ثم أتى النبي ﷺ مكروبًا فطمأنه، ويذكر المفسرون هذه الآية في شأنه."] },
  { id: "srm-055", s: "seerah", g: 3, d: 3, t: ["early-muslims", "umar"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the conversion of ʿUmar",
    en: ["In whose house was ʿUmar ibn al-Khaṭṭāb moved by hearing the Quran before he accepted Islam?", ["His sister Fāṭima and her husband Saʿīd ibn Zayd", "Abū Bakr al-Ṣiddīq", "al-Arqam ibn Abī al-Arqam", "Ḥamza ibn ʿAbd al-Muṭṭalib"], "According to Ibn Isḥāq, ʿUmar burst into his sister's house, struck her, then read the opening of Sūrat Ṭā Hā from a sheet and went to the Prophet at Dār al-Arqam to accept Islam."],
    de: ["In wessen Haus wurde ʿUmar ibn al-Chaṭṭāb vom Hören des Qurʾān bewegt, bevor er den Islam annahm?", ["Bei seiner Schwester Fāṭima und ihrem Mann Saʿīd ibn Zaid", "Bei Abū Bakr aṣ-Ṣiddīq", "Bei al-Arqam ibn Abī al-Arqam", "Bei Ḥamza ibn ʿAbd al-Muṭṭalib"], "Nach Ibn Isḥāq drang ʿUmar in das Haus seiner Schwester ein, schlug sie, las dann den Anfang der Sure Ṭā Hā von einem Blatt und ging zum Propheten in Dār al-Arqam, um den Islam anzunehmen."],
    ar: ["في بيت مَن تأثّر عمر بن الخطاب بسماع القرآن قبل إسلامه؟", ["بيت أخته فاطمة وزوجها سعيد بن زيد", "بيت أبي بكر الصديق", "بيت الأرقم بن أبي الأرقم", "بيت حمزة بن عبد المطلب"], "ذكر ابن إسحاق أن عمر دخل على أخته فضربها، ثم قرأ صدر سورة طه من صحيفة، فمضى إلى النبي ﷺ في دار الأرقم فأسلم."] },
  { id: "srm-056", s: "seerah", g: 3, d: 3, t: ["abyssinia", "jafar"], src: "Musnad Aḥmad, hadith of Umm Salama on the emigration to Abyssinia",
    en: ["When al-Najāshī asked to hear something of the revelation, from which sūra did Jaʿfar recite?", ["Sūrat Maryam", "Sūrat Yā Sīn", "Sūrat al-Kahf", "Sūrat Āl ʿImrān"], "Jaʿfar recited the opening of Sūrat Maryam, about Zakariyyā, Yaḥyā, Maryam and ʿĪsā; the king wept until his beard was wet, as did his bishops. Āl ʿImrān is a Medinan sūra."],
    de: ["Als an-Nadschāschī etwas von der Offenbarung hören wollte, aus welcher Sure trug Dschaʿfar vor?", ["Sure Maryam", "Sure Yā Sīn", "Sure al-Kahf", "Sure Āl ʿImrān"], "Dschaʿfar trug den Anfang der Sure Maryam vor, über Zakariyyā, Yaḥyā, Maryam und ʿĪsā; der König weinte, bis sein Bart nass war, ebenso seine Bischöfe. Āl ʿImrān ist eine medinensische Sure."],
    ar: ["لما طلب النجاشي أن يسمع شيئًا مما جاء به النبي ﷺ، من أي سورة قرأ جعفر؟", ["سورة مريم", "سورة يس", "سورة الكهف", "سورة آل عمران"], "قرأ جعفر صدر سورة مريم في خبر زكريا ويحيى ومريم وعيسى، فبكى النجاشي حتى اخضلّت لحيته وبكى أساقفته؛ أما آل عمران فسورة مدنية."] },
  { id: "srm-057", s: "seerah", g: 3, d: 4, t: ["abyssinia", "najashi"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Janāʾiz, announcing a death and praying over the absent",
    en: ["What did the Prophet do in Medina on the day al-Najāshī died?", ["He announced his death and led a funeral prayer for him in absentia", "He sent Jaʿfar back to Abyssinia to bury him", "He declared three days of mourning in Medina", "He wrote to the new king demanding the Muslims' return"], "al-Bukhārī reports that he announced the Negus's death on the day he died, went out with the Companions to the prayer place and prayed over him with four takbīrs."],
    de: ["Was tat der Prophet in Medina am Todestag an-Nadschāschīs?", ["Er gab seinen Tod bekannt und leitete für ihn ein Totengebet in Abwesenheit", "Er schickte Dschaʿfar nach Abessinien zurück, um ihn zu bestatten", "Er rief in Medina drei Tage Trauer aus", "Er schrieb dem neuen König und verlangte die Rückkehr der Muslime"], "Al-Buchārī berichtet, dass er den Tod des Negus noch an dessen Todestag bekanntgab, mit den Gefährten zum Gebetsplatz hinausging und mit vier Takbīrs über ihn betete."],
    ar: ["ماذا فعل النبي ﷺ في المدينة يوم مات النجاشي؟", ["نعاه وصلّى عليه صلاة الغائب", "أرسل جعفرًا إلى الحبشة ليدفنه", "أعلن الحداد ثلاثة أيام في المدينة", "كتب إلى الملك الجديد يطلب رجوع المسلمين"], "روى البخاري أنه نعى النجاشي في اليوم الذي مات فيه، وخرج بأصحابه إلى المصلّى فصلى عليه وكبّر أربعًا."] },
  { id: "srm-058", s: "seerah", g: 3, d: 3, t: ["boycott"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the annulment of the boycott document",
    en: ["What, according to the sīra reports, had happened to the boycott document hung in the Kaʿba when it was taken down?", ["Termites had eaten it except the words naming God", "It had been stolen by a Hāshimite youth", "Rain had washed the writing away completely", "It had been burnt in a fire at the Kaʿba"], "The Prophet told Abū Ṭālib that the document had been consumed except where God's name was written; when Quraysh checked, they found it so, which helped bring the boycott to an end."],
    de: ["Was war nach den Sīra-Berichten mit dem in der Kaʿba aufgehängten Boykottschreiben geschehen, als man es abnahm?", ["Termiten hatten es bis auf die Worte mit dem Namen Gottes gefressen", "Ein junger Hāschimit hatte es gestohlen", "Regen hatte die Schrift völlig fortgewaschen", "Es war bei einem Brand an der Kaʿba verbrannt"], "Der Prophet sagte Abū Ṭālib, das Schreiben sei bis auf die Stelle mit dem Namen Gottes aufgezehrt; als die Quraisch nachsahen, fanden sie es so, was zur Beendigung des Boykotts beitrug."],
    ar: ["ماذا وجدت قريش في صحيفة المقاطعة المعلقة في الكعبة حين أنزلوها، بحسب أخبار السيرة؟", ["أكلتها الأَرَضة إلا ما فيه اسم الله", "سرقها فتى من بني هاشم", "محا المطر كتابتها كلها", "احترقت في حريق أصاب الكعبة"], "أخبر النبي ﷺ أبا طالب أن الأَرَضة أكلت الصحيفة إلا اسم الله، فلما نظرت قريش وجدوها كذلك، فكان ذلك مما أعان على نقضها."] },
  { id: "srm-059", s: "seerah", g: 3, d: 3, t: ["taif"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the journey to al-Ṭāʾif",
    en: ["Who was ʿAddās, whom the Prophet met in a garden outside al-Ṭāʾif?", ["A Christian servant from Nineveh who brought him grapes", "A chief of Thaqīf who apologised to him", "A Jewish scholar who recognised his description", "A shepherd who guided him back to Mecca"], "The sons of Rabīʿa sent their servant ʿAddās with grapes; when he learned that the Prophet knew of Yūnus of Nineveh, ʿAddās kissed his head and hands."],
    de: ["Wer war ʿAddās, dem der Prophet in einem Garten außerhalb von aṭ-Ṭāʾif begegnete?", ["Ein christlicher Diener aus Ninive, der ihm Trauben brachte", "Ein Oberhaupt der Thaqīf, das sich bei ihm entschuldigte", "Ein jüdischer Gelehrter, der seine Beschreibung erkannte", "Ein Hirte, der ihn nach Mekka zurückführte"], "Die Söhne Rabīʿas schickten ihren Diener ʿAddās mit Trauben; als dieser hörte, dass der Prophet Yūnus von Ninive kannte, küsste er ihm Kopf und Hände."],
    ar: ["مَن عدّاس الذي لقيه النبي ﷺ في بستان خارج الطائف؟", ["غلام نصراني من نينوى قدّم له عنبًا", "سيد من ثقيف اعتذر إليه", "حبر يهودي عرف صفته", "راعٍ دلّه على طريق مكة"], "أرسل ابنا ربيعة غلامهما عدّاسًا بقطف عنب، فلما علم أن النبي ﷺ يعرف يونس بن متّى من نينوى أكبّ عليه يقبّل رأسه ويديه."] },
  { id: "srm-060", s: "seerah", g: 3, d: 4, t: ["taif", "prophetic-mercy"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Badʾ al-Khalq, hadith of ʿĀʾisha on the hardest day",
    en: ["After al-Ṭāʾif, the angel of the mountains offered to crush its people between the two mountains. How did the Prophet answer?", ["He hoped God would bring from their descendants people who worship Him alone", "He accepted and asked for a sign first", "He asked that only their leaders be punished", "He asked for the punishment to be delayed one year"], "In ʿĀʾisha's report the Prophet called this his hardest day; yet he declined the offer, hoping their offspring would worship God without partners. Thaqīf did enter Islam in 9 AH."],
    de: ["Nach aṭ-Ṭāʾif bot der Engel der Berge an, die Bewohner zwischen den beiden Bergen zu zermalmen. Wie antwortete der Prophet?", ["Er hoffte, Gott werde aus ihren Nachkommen Menschen hervorbringen, die Ihn allein anbeten", "Er nahm an und bat zuerst um ein Zeichen", "Er bat, nur ihre Oberhäupter zu bestrafen", "Er bat, die Strafe um ein Jahr aufzuschieben"], "In ʿĀʾischas Bericht nannte der Prophet dies seinen schwersten Tag; dennoch lehnte er ab, in der Hoffnung, ihre Nachkommen würden Gott ohne Teilhaber anbeten. Die Thaqīf nahmen im Jahr 9 n. H. den Islam an."],
    ar: ["بعد الطائف عرض ملك الجبال أن يُطبق على أهلها الأخشبين. بماذا أجاب النبي ﷺ؟", ["رجا أن يُخرج الله من أصلابهم من يعبده وحده", "قبل وطلب آية أولًا", "طلب أن يُعاقب سادتهم فقط", "طلب تأخير العذاب سنة"], "في حديث عائشة سمّى النبي ﷺ ذلك أشدّ ما لقي، ومع ذلك أبى ورجا أن يخرج من أصلابهم من يعبد الله لا يشرك به شيئًا؛ وقد أسلمت ثقيف سنة تسع."] },
  { id: "srm-061", s: "seerah", g: 3, d: 3, t: ["isra-miraj", "salah"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Ṣalāt, how prayer was prescribed on the Night Journey",
    en: ["During the Miʿrāj, which prophet urged the Prophet to return and ask for the number of prayers to be reduced?", ["Mūsā", "Ibrāhīm", "ʿĪsā", "Ādam"], "On his way back, Mūsā told him his community would not manage fifty prayers, drawing on his experience with the Children of Israel, and he returned repeatedly until they were five."],
    de: ["Welcher Prophet drängte den Propheten während des Miʿrādsch, zurückzukehren und um eine Verringerung der Gebete zu bitten?", ["Mūsā", "Ibrāhīm", "ʿĪsā", "Ādam"], "Auf dem Rückweg sagte Mūsā ihm aus seiner Erfahrung mit den Kindern Israels, seine Gemeinde werde fünfzig Gebete nicht schaffen; er kehrte mehrmals zurück, bis es fünf waren."],
    ar: ["في المعراج، أيّ نبي حثّ النبي ﷺ على الرجوع وسؤال التخفيف في عدد الصلوات؟", ["موسى", "إبراهيم", "عيسى", "آدم"], "قال له موسى في رجوعه إن أمته لا تطيق خمسين صلاة، مستندًا إلى تجربته مع بني إسرائيل، فما زال يراجع حتى صارت خمسًا."] },
  { id: "srm-062", s: "seerah", g: 3, d: 3, t: ["aqaba", "musab"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the first pledge of al-ʿAqaba",
    en: ["Whom did the Prophet send to Yathrib after the first pledge of al-ʿAqaba to teach the Quran and Islam?", ["Muṣʿab ibn ʿUmayr", "Abū ʿUbayda ibn al-Jarrāḥ", "Ḥamza ibn ʿAbd al-Muṭṭalib", "ʿAbd al-Raḥmān ibn ʿAwf"], "Muṣʿab, a young man of Quraysh, taught in Yathrib and was called al-Muqriʾ; leading men such as Saʿd ibn Muʿādh and Usayd ibn Ḥuḍayr accepted Islam through him."],
    de: ["Wen sandte der Prophet nach dem ersten Eid von al-ʿAqaba nach Yathrib, um den Qurʾān und den Islam zu lehren?", ["Muṣʿab ibn ʿUmair", "Abū ʿUbaida ibn al-Dscharrāḥ", "Ḥamza ibn ʿAbd al-Muṭṭalib", "ʿAbd ar-Raḥmān ibn ʿAuf"], "Muṣʿab, ein junger Mann der Quraisch, lehrte in Yathrib und wurde al-Muqriʾ genannt; führende Männer wie Saʿd ibn Muʿādh und Usaid ibn Ḥuḍair nahmen durch ihn den Islam an."],
    ar: ["مَن بعثه النبي ﷺ إلى يثرب بعد بيعة العقبة الأولى ليعلّم القرآن والإسلام؟", ["مصعب بن عمير", "أبو عبيدة بن الجراح", "حمزة بن عبد المطلب", "عبد الرحمن بن عوف"], "علّم مصعب، الفتى القرشي، في يثرب وسُمّي المقرئ، وأسلم على يديه سادة مثل سعد بن معاذ وأسيد بن حضير."] },
  { id: "srm-063", s: "seerah", g: 3, d: 3, t: ["hijra", "quba"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the arrival at Qubāʾ",
    en: ["Which mosque did the Prophet found on arrival at the edge of Yathrib, before entering the town itself?", ["The mosque of Qubāʾ", "The mosque of the two qiblas", "The Prophet's Mosque", "The mosque of al-Jumuʿa"], "He first stayed at Qubāʾ with Banū ʿAmr ibn ʿAwf and founded its mosque, commonly called the first mosque built in Islam. The Prophet's Mosque was built after he moved into the town."],
    de: ["Welche Moschee gründete der Prophet bei seiner Ankunft am Rand von Yathrib, bevor er die Stadt selbst betrat?", ["Die Moschee von Qubāʾ", "Die Moschee der zwei Gebetsrichtungen", "Die Prophetenmoschee", "Die Moschee al-Dschumuʿa"], "Er wohnte zuerst in Qubāʾ bei den Banū ʿAmr ibn ʿAuf und gründete dort die Moschee, die gemeinhin als erste im Islam erbaute Moschee gilt. Die Prophetenmoschee entstand nach seinem Einzug in die Stadt."],
    ar: ["أيّ مسجد أسّسه النبي ﷺ عند وصوله إلى طرف يثرب قبل دخول البلدة نفسها؟", ["مسجد قباء", "مسجد القبلتين", "المسجد النبوي", "مسجد الجمعة"], "نزل أولًا بقباء في بني عمرو بن عوف وأسس مسجدها، وهو المشهور بأنه أول مسجد بُني في الإسلام؛ أما المسجد النبوي فبُني بعد أن دخل البلدة."] },
  { id: "srm-064", s: "seerah", g: 3, d: 4, t: ["hijra", "opposition-of-quraysh"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the council of Quraysh in Dār al-Nadwa",
    en: ["Which plan against the Prophet did Quraysh adopt in Dār al-Nadwa shortly before the Hijra?", ["A young man from each clan would strike him together", "He would be imprisoned in a locked house", "He would be banished from Mecca for good", "He would be handed over to Thaqīf"], "On Abū Jahl's proposal, a strong youth from every clan was to strike him at once so that his blood would be spread among all the clans and Banū Hāshim could not take revenge. Imprisonment and exile were proposed and rejected."],
    de: ["Welchen Plan gegen den Propheten beschlossen die Quraisch kurz vor der Hidschra in Dār an-Nadwa?", ["Ein junger Mann aus jedem Clan sollte gemeinsam mit den anderen zuschlagen", "Er sollte in einem verschlossenen Haus eingesperrt werden", "Er sollte für immer aus Mekka verbannt werden", "Er sollte den Thaqīf ausgeliefert werden"], "Auf Abū Dschahls Vorschlag sollte ein starker junger Mann aus jedem Clan gleichzeitig zuschlagen, damit sein Blut auf alle Clans verteilt sei und die Banū Hāschim keine Rache nehmen könnten. Gefangenschaft und Verbannung wurden vorgeschlagen und verworfen."],
    ar: ["أي خطة اعتمدتها قريش في دار الندوة ضد النبي ﷺ قبيل الهجرة؟", ["أن يضربه فتى من كل قبيلة ضربة رجل واحد", "أن يُحبس في بيت مغلق", "أن يُنفى من مكة إلى الأبد", "أن يُسلَّم إلى ثقيف"], "اقترح أبو جهل أن يُؤخذ من كل قبيلة فتى جلد فيضربوه ضربة رجل واحد فيتفرق دمه في القبائل فلا يقدر بنو هاشم على الثأر؛ وقد طُرح الحبس والنفي ثم رُدّا."] },
  // ---------- stage 4 ----------
  { id: "srm-065", s: "seerah", g: 4, d: 4, t: ["abd-al-muttalib", "lineage"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, ʿAbd al-Muṭṭalib's vow to sacrifice a son",
    en: ["ʿAbd al-Muṭṭalib had vowed to sacrifice one of his sons, and the lot fell on ʿAbdullāh. How, according to the sīra reports, was ʿAbdullāh ransomed?", ["With one hundred camels, after lots were cast repeatedly", "With forty sheep slaughtered at the Kaʿba", "With ten camels and a gift to the idol Hubal", "With his weight in silver given to the poor"], "Lots were cast between ʿAbdullāh and ten camels, and the number was raised by ten each time until the lot fell on the camels at one hundred. This is why the Prophet is sometimes called the son of the two sacrificial ones (Ismāʿīl and ʿAbdullāh)."],
    de: ["ʿAbd al-Muṭṭalib hatte gelobt, einen seiner Söhne zu opfern, und das Los fiel auf ʿAbdullāh. Wie wurde ʿAbdullāh nach den Sīra-Berichten ausgelöst?", ["Mit hundert Kamelen, nachdem wiederholt das Los geworfen wurde", "Mit vierzig an der Kaʿba geschlachteten Schafen", "Mit zehn Kamelen und einer Gabe an den Götzen Hubal", "Mit seinem Gewicht in Silber für die Armen"], "Man warf das Los zwischen ʿAbdullāh und zehn Kamelen und erhöhte jedes Mal um zehn, bis es bei hundert auf die Kamele fiel. Daher wird der Prophet bisweilen Sohn der beiden Opfer (Ismāʿīl und ʿAbdullāh) genannt."],
    ar: ["نذر عبد المطلب أن ينحر أحد أبنائه فخرج السهم على عبد الله. بمَ فُدي عبد الله بحسب أخبار السيرة؟", ["بمئة من الإبل بعد تكرار القرعة", "بأربعين شاة ذُبحت عند الكعبة", "بعشر من الإبل وهدية لهبل", "بوزنه فضة للفقراء"], "أُقرع بين عبد الله وعشر من الإبل، وكلما خرج السهم عليه زيد عشرًا، حتى خرج على الإبل عند المئة؛ ولذا يُقال للنبي ﷺ ابن الذبيحين: إسماعيل وعبد الله."] },
  { id: "srm-066", s: "seerah", g: 4, d: 4, t: ["lineage", "yathrib"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the marriage of Hāshim and the birth of ʿAbd al-Muṭṭalib",
    en: ["ʿAbd al-Muṭṭalib's mother, Salmā bint ʿAmr, came from Yathrib. To which clan did she belong, giving the Prophet kinship ties there?", ["Banū ʿAdī ibn al-Najjār of the Khazraj", "Banū ʿAbd al-Ashhal of the Aws", "Banū Qaynuqāʿ", "Banū ʿAmr ibn ʿAwf of the Aws"], "Hāshim married Salmā of Banū ʿAdī ibn al-Najjār, and ʿAbd al-Muṭṭalib (Shayba) grew up in Yathrib. This is why Banū al-Najjār were called the maternal relatives of the Prophet's family."],
    de: ["ʿAbd al-Muṭṭalibs Mutter Salmā bint ʿAmr stammte aus Yathrib. Zu welchem Clan gehörte sie, wodurch der Prophet dort Verwandte hatte?", ["Banū ʿAdī ibn an-Naddschār von den Chazradsch", "Banū ʿAbd al-Aschhal von den Aus", "Banū Qainuqāʿ", "Banū ʿAmr ibn ʿAuf von den Aus"], "Hāschim heiratete Salmā von den Banū ʿAdī ibn an-Naddschār, und ʿAbd al-Muṭṭalib (Schaiba) wuchs in Yathrib auf. Deshalb galten die Banū an-Naddschār als mütterliche Verwandte der Familie des Propheten."],
    ar: ["كانت سلمى بنت عمرو، أم عبد المطلب، من أهل يثرب. من أيّ بطن كانت، فصارت للنبي ﷺ فيها قرابة؟", ["بنو عدي بن النجار من الخزرج", "بنو عبد الأشهل من الأوس", "بنو قينقاع", "بنو عمرو بن عوف من الأوس"], "تزوج هاشم سلمى من بني عدي بن النجار، ونشأ عبد المطلب (شيبة) بيثرب؛ ولذلك عُدّ بنو النجار أخوال آل النبي ﷺ."] },
  { id: "srm-067", s: "seerah", g: 4, d: 4, t: ["pre-islamic-arabia", "idolatry"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Manāqib, the story of Khuzāʿa; Ibn Hishām, al-Sīra al-Nabawiyya, the idols of the Arabs",
    en: ["Which man is described in the sīra as the first to alter the religion of Ibrāhīm in Mecca by introducing idols and the sāʾiba custom?", ["ʿAmr ibn Luḥayy al-Khuzāʿī", "Quṣayy ibn Kilāb", "Kaʿb ibn Luʾayy", "Abraha al-Ashram"], "Ibn Isḥāq reports that ʿAmr ibn Luḥayy of Khuzāʿa brought idols to Mecca, and al-Bukhārī records that he was the first to institute the sāʾiba (camels set free for idols). Quṣayy later took control of Mecca from Khuzāʿa."],
    de: ["Welcher Mann gilt in der Sīra als der Erste, der in Mekka die Religion Ibrāhīms durch Götzen und den Brauch der Sāʾiba veränderte?", ["ʿAmr ibn Luḥayy al-Chuzāʿī", "Quṣayy ibn Kilāb", "Kaʿb ibn Luʾayy", "Abraha al-Aschram"], "Ibn Isḥāq berichtet, dass ʿAmr ibn Luḥayy von den Chuzāʿa Götzen nach Mekka brachte, und al-Buchārī überliefert, dass er als Erster die Sāʾiba (für Götzen freigelassene Kamele) einführte. Quṣayy übernahm später Mekka von den Chuzāʿa."],
    ar: ["مَن الرجل الذي تذكر كتب السيرة أنه أول من غيّر دين إبراهيم بمكة فجلب الأصنام وسيّب السوائب؟", ["عمرو بن لحي الخزاعي", "قصي بن كلاب", "كعب بن لؤي", "أبرهة الأشرم"], "ذكر ابن إسحاق أن عمرو بن لحي الخزاعي جلب الأصنام إلى مكة، وفي البخاري أنه أول من سيّب السوائب؛ أما قصي فانتزع أمر مكة من خزاعة بعد ذلك."] },
  { id: "srm-068", s: "seerah", g: 4, d: 5, t: ["pre-islamic-arabia", "hunafa"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Manāqib al-Anṣār, the account of Zayd ibn ʿAmr ibn Nufayl",
    en: ["Which pre-Islamic seeker of the religion of Ibrāhīm refused to eat meat sacrificed to idols, died before the call began, and was the father of one of the ten promised Paradise?", ["Zayd ibn ʿAmr ibn Nufayl", "Waraqa ibn Nawfal", "Umayya ibn Abī al-Ṣalt", "Quss ibn Sāʿida"], "al-Bukhārī reports that Zayd ibn ʿAmr rejected idol sacrifices and sought the ḥanīf religion; his son Saʿīd ibn Zayd is among the ten. Waraqa became a Christian and lived to meet the Prophet after the first revelation."],
    de: ["Welcher vorislamische Sucher der Religion Ibrāhīms aß kein Götzenopferfleisch, starb vor Beginn der Verkündigung und war Vater eines der zehn, denen das Paradies verheißen wurde?", ["Zaid ibn ʿAmr ibn Nufail", "Waraqa ibn Naufal", "Umayya ibn Abī ṣ-Ṣalt", "Quss ibn Sāʿida"], "Al-Buchārī berichtet, dass Zaid ibn ʿAmr Götzenopfer ablehnte und die ḥanīfische Religion suchte; sein Sohn Saʿīd ibn Zaid gehört zu den Zehn. Waraqa wurde Christ und erlebte den Propheten nach der ersten Offenbarung."],
    ar: ["مَن الباحث عن دين إبراهيم في الجاهلية الذي امتنع عن أكل ما ذُبح للأصنام ومات قبل البعثة، وابنه أحد العشرة المبشرين؟", ["زيد بن عمرو بن نفيل", "ورقة بن نوفل", "أمية بن أبي الصلت", "قس بن ساعدة"], "روى البخاري أن زيد بن عمرو كان يأبى ذبائح الأصنام ويطلب الحنيفية، وابنه سعيد بن زيد من العشرة؛ أما ورقة فتنصّر وأدرك النبي ﷺ بعد أول الوحي."] },
  { id: "srm-069", s: "seerah", g: 4, d: 5, t: ["hilf-al-fudul"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, Ḥilf al-Fuḍūl; al-Suhaylī, al-Rawḍ al-Unuf",
    en: ["Which incident is commonly reported as the trigger for Ḥilf al-Fuḍūl?", ["A merchant from Zabīd whose payment al-ʿĀṣ ibn Wāʾil withheld", "The killing of a man of Thaqīf at the fair of ʿUkāẓ", "A theft from the treasury of the Kaʿba", "A quarrel between two clans over the well of Zamzam"], "A trader from Zabīd in Yemen sold goods to al-ʿĀṣ ibn Wāʾil, who refused to pay; his appeal to Quraysh led several clans to meet in the house of ʿAbdullāh ibn Judʿān and pledge to uphold the rights of the wronged. The ʿUkāẓ killing belongs to the Fijār war."],
    de: ["Welcher Vorfall wird gewöhnlich als Anlass des Ḥilf al-Fuḍūl berichtet?", ["Ein Händler aus Zabīd, dem al-ʿĀṣ ibn Wāʾil die Bezahlung verweigerte", "Die Tötung eines Mannes der Thaqīf auf dem Markt von ʿUkāẓ", "Ein Diebstahl aus dem Schatz der Kaʿba", "Ein Streit zweier Clans um den Brunnen Zamzam"], "Ein Händler aus Zabīd im Jemen verkaufte Waren an al-ʿĀṣ ibn Wāʾil, der nicht bezahlte; sein Hilferuf an die Quraisch führte dazu, dass sich mehrere Clans im Haus ʿAbdullāh ibn Dschudʿāns versammelten und schworen, den Rechten der Benachteiligten Geltung zu verschaffen. Die Tötung bei ʿUkāẓ gehört zum Fidschār-Krieg."],
    ar: ["ما الحادثة التي تُذكر عادة سببًا لحلف الفضول؟", ["رجل من زَبيد حبس العاص بن وائل ثمن بضاعته", "قتل رجل من ثقيف في سوق عكاظ", "سرقة من كنز الكعبة", "نزاع بين بطنين على بئر زمزم"], "باع رجل من زبيد باليمن بضاعة للعاص بن وائل فحبس عنه حقه، فاستغاث بقريش، فاجتمعت بطون منها في دار عبد الله بن جدعان وتعاقدوا على نصرة المظلوم؛ أما قتل عكاظ فمن أسباب حرب الفجار."] },
  { id: "srm-070", s: "seerah", g: 4, d: 4, t: ["kaaba-rebuilding"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the rebuilding of the Kaʿba",
    en: ["When Quraysh feared to begin demolishing the old Kaʿba, who struck the first blow?", ["al-Walīd ibn al-Mughīra", "Abū Ṭālib ibn ʿAbd al-Muṭṭalib", "ʿUtba ibn Rabīʿa", "Abū Sufyān ibn Ḥarb"], "Ibn Isḥāq reports that al-Walīd ibn al-Mughīra of Makhzūm took up a pickaxe and began; the others waited a night, and when no harm befell him they joined in."],
    de: ["Als die Quraisch sich fürchteten, mit dem Abriss der alten Kaʿba zu beginnen, wer tat den ersten Schlag?", ["al-Walīd ibn al-Mughīra", "Abū Ṭālib ibn ʿAbd al-Muṭṭalib", "ʿUtba ibn Rabīʿa", "Abū Sufyān ibn Ḥarb"], "Ibn Isḥāq berichtet, dass al-Walīd ibn al-Mughīra von den Machzūm eine Spitzhacke nahm und begann; die anderen warteten eine Nacht, und als ihm nichts geschah, machten sie mit."],
    ar: ["لما هابت قريش هدم الكعبة القديمة، مَن بدأ الهدم؟", ["الوليد بن المغيرة", "أبو طالب بن عبد المطلب", "عتبة بن ربيعة", "أبو سفيان بن حرب"], "ذكر ابن إسحاق أن الوليد بن المغيرة المخزومي أخذ المعول فبدأ، فتربّص الناس ليلتهم، فلما لم يصبه شيء هدموا معه."] },
  { id: "srm-071", s: "seerah", g: 4, d: 4, t: ["opposition-of-quraysh", "public-call"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, ʿUtba ibn Rabīʿa's offer",
    en: ["When ʿUtba ibn Rabīʿa offered the Prophet wealth, leadership or a cure in return for abandoning his call, what was the Prophet's response?", ["He recited the opening of Sūrat Fuṣṣilat", "He recited the whole of Sūrat al-Kāfirūn", "He gave a speech on the unity of God", "He walked away without a word"], "According to Ibn Isḥāq, he listened to ʿUtba to the end and then recited the opening of Fuṣṣilat; ʿUtba returned to Quraysh shaken and advised them to leave him alone."],
    de: ["Als ʿUtba ibn Rabīʿa dem Propheten Reichtum, Herrschaft oder Heilung anbot, damit er seine Verkündigung aufgebe, wie antwortete der Prophet?", ["Er trug den Anfang der Sure Fuṣṣilat vor", "Er trug die ganze Sure al-Kāfirūn vor", "Er hielt eine Rede über die Einheit Gottes", "Er ging wortlos fort"], "Nach Ibn Isḥāq hörte er ʿUtba bis zum Ende zu und trug dann den Anfang von Fuṣṣilat vor; ʿUtba kehrte erschüttert zu den Quraisch zurück und riet ihnen, ihn in Ruhe zu lassen."],
    ar: ["لما عرض عتبة بن ربيعة على النبي ﷺ المال أو الملك أو العلاج ليترك دعوته، كيف أجابه؟", ["تلا عليه صدر سورة فصلت", "تلا عليه سورة الكافرون كاملة", "خطب فيه خطبة في التوحيد", "انصرف عنه دون كلام"], "ذكر ابن إسحاق أنه استمع لعتبة حتى فرغ ثم تلا عليه صدر سورة فصلت، فرجع عتبة إلى قريش متأثرًا وأشار عليهم أن يخلّوا بينه وبين العرب."] },
  { id: "srm-072", s: "seerah", g: 4, d: 4, t: ["abyssinia", "opposition-of-quraysh"], src: "Musnad Aḥmad, hadith of Umm Salama on the emigration to Abyssinia",
    en: ["Which two envoys did Quraysh send to al-Najāshī to have the emigrants handed back?", ["ʿAmr ibn al-ʿĀṣ and ʿAbdullāh ibn Abī Rabīʿa", "Abū Sufyān and Suhayl ibn ʿAmr", "Abū Jahl and Umayya ibn Khalaf", "Khālid ibn al-Walīd and ʿIkrima ibn Abī Jahl"], "In Umm Salama's account, Quraysh sent ʿAmr ibn al-ʿĀṣ and ʿAbdullāh ibn Abī Rabīʿa with gifts for the king and his patriarchs, but al-Najāshī refused to surrender the Muslims after hearing Jaʿfar."],
    de: ["Welche beiden Gesandten schickten die Quraisch zu an-Nadschāschī, um die Auswanderer zurückzuholen?", ["ʿAmr ibn al-ʿĀṣ und ʿAbdullāh ibn Abī Rabīʿa", "Abū Sufyān und Suhail ibn ʿAmr", "Abū Dschahl und Umayya ibn Chalaf", "Chālid ibn al-Walīd und ʿIkrima ibn Abī Dschahl"], "Nach Umm Salamas Bericht schickten die Quraisch ʿAmr ibn al-ʿĀṣ und ʿAbdullāh ibn Abī Rabīʿa mit Geschenken für den König und seine Patriarchen, doch an-Nadschāschī lieferte die Muslime nach Dschaʿfars Rede nicht aus."],
    ar: ["مَن الرسولان اللذان بعثتهما قريش إلى النجاشي ليردّ المهاجرين؟", ["عمرو بن العاص وعبد الله بن أبي ربيعة", "أبو سفيان وسهيل بن عمرو", "أبو جهل وأمية بن خلف", "خالد بن الوليد وعكرمة بن أبي جهل"], "في رواية أم سلمة بعثت قريش عمرو بن العاص وعبد الله بن أبي ربيعة بهدايا للملك وبطارقته، فأبى النجاشي أن يسلّم المسلمين بعد أن سمع جعفرًا."] },
  { id: "srm-073", s: "seerah", g: 4, d: 5, t: ["abyssinia", "chronology"], src: "Ibn Saʿd, al-Ṭabaqāt al-Kubrā, the first emigration to Abyssinia; Ibn Hishām, al-Sīra al-Nabawiyya",
    en: ["Why did some of the first emigrants to Abyssinia return to Mecca after a few months?", ["They heard a false report that Quraysh had accepted Islam", "Al-Najāshī expelled them under pressure from Quraysh", "A war broke out between Abyssinia and Yemen", "The Prophet called them back for the pledge of al-ʿAqaba"], "The first emigration, commonly dated to Rajab of the fifth year of prophethood, was cut short by a rumour that Quraysh had embraced Islam. Finding it untrue, most returned, and a larger second emigration followed."],
    de: ["Warum kehrten einige der ersten Auswanderer nach Abessinien nach wenigen Monaten nach Mekka zurück?", ["Sie hörten das falsche Gerücht, die Quraisch hätten den Islam angenommen", "An-Nadschāschī wies sie auf Druck der Quraisch aus", "Zwischen Abessinien und dem Jemen brach ein Krieg aus", "Der Prophet rief sie zum Eid von al-ʿAqaba zurück"], "Die erste Auswanderung, meist auf den Radschab des fünften Jahres des Prophetentums datiert, wurde durch ein Gerücht abgebrochen, die Quraisch hätten den Islam angenommen. Als es sich als falsch erwies, zogen die meisten wieder fort, und eine größere zweite Auswanderung folgte."],
    ar: ["لماذا رجع بعض المهاجرين الأوائل من الحبشة إلى مكة بعد أشهر قليلة؟", ["بلغهم خبر كاذب أن قريشًا أسلمت", "أخرجهم النجاشي بضغط من قريش", "نشبت حرب بين الحبشة واليمن", "استدعاهم النبي ﷺ لبيعة العقبة"], "الهجرة الأولى، وتُؤرَّخ في المشهور برجب من السنة الخامسة للبعثة، انقطعت بإشاعة أن قريشًا أسلمت، فلما تبيّن كذبها عاد أكثرهم، ثم كانت الهجرة الثانية بعدد أكبر."] },
  { id: "srm-074", s: "seerah", g: 4, d: 5, t: ["boycott"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the annulment of the boycott document",
    en: ["Which Meccan is credited by Ibn Isḥāq with starting the effort among Quraysh to annul the boycott document?", ["Hishām ibn ʿAmr", "Abū Sufyān ibn Ḥarb", "ʿUtba ibn Rabīʿa", "al-Walīd ibn al-Mughīra"], "Hishām ibn ʿAmr, who had secretly brought food into the ravine, won over Zuhayr ibn Abī Umayya, al-Muṭʿim ibn ʿAdī, Abū al-Bakhtarī and Zamʿa ibn al-Aswad, and together they publicly demanded that the document be torn up."],
    de: ["Wem schreibt Ibn Isḥāq den Anstoß unter den Quraisch zu, das Boykottschreiben aufzuheben?", ["Hischām ibn ʿAmr", "Abū Sufyān ibn Ḥarb", "ʿUtba ibn Rabīʿa", "al-Walīd ibn al-Mughīra"], "Hischām ibn ʿAmr, der heimlich Lebensmittel in die Schlucht gebracht hatte, gewann Zuhair ibn Abī Umayya, al-Muṭʿim ibn ʿAdī, Abū l-Bachtarī und Zamʿa ibn al-Aswad, und gemeinsam verlangten sie öffentlich, das Schreiben zu zerreißen."],
    ar: ["مَن الذي ينسب إليه ابن إسحاق السعي بين قريش لنقض صحيفة المقاطعة؟", ["هشام بن عمرو", "أبو سفيان بن حرب", "عتبة بن ربيعة", "الوليد بن المغيرة"], "كان هشام بن عمرو يُدخل الطعام إلى الشعب سرًّا، فاستمال زهير بن أبي أمية والمطعم بن عدي وأبا البختري وزمعة بن الأسود، فقاموا معًا يطالبون بشقّ الصحيفة."] },
  { id: "srm-075", s: "seerah", g: 4, d: 4, t: ["taif", "protection-jiwar"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the return from al-Ṭāʾif",
    en: ["Under whose protection (jiwār) did the Prophet re-enter Mecca after returning from al-Ṭāʾif?", ["al-Muṭʿim ibn ʿAdī", "Abū Lahab ibn ʿAbd al-Muṭṭalib", "al-Akhnas ibn Sharīq", "Suhayl ibn ʿAmr"], "al-Akhnas and Suhayl declined to grant protection; al-Muṭʿim ibn ʿAdī agreed and stood armed with his sons at the Kaʿba while the Prophet performed ṭawāf. The Prophet later remembered this kindness."],
    de: ["Unter wessen Schutz (Dschiwār) betrat der Prophet Mekka wieder, nachdem er aus aṭ-Ṭāʾif zurückgekehrt war?", ["al-Muṭʿim ibn ʿAdī", "Abū Lahab ibn ʿAbd al-Muṭṭalib", "al-Achnas ibn Scharīq", "Suhail ibn ʿAmr"], "Al-Achnas und Suhail lehnten den Schutz ab; al-Muṭʿim ibn ʿAdī willigte ein und stand mit seinen Söhnen bewaffnet an der Kaʿba, während der Prophet den Ṭawāf vollzog. Der Prophet erinnerte sich später dieser Güte."],
    ar: ["في جوار مَن دخل النبي ﷺ مكة بعد رجوعه من الطائف؟", ["المطعم بن عدي", "أبي لهب بن عبد المطلب", "الأخنس بن شريق", "سهيل بن عمرو"], "اعتذر الأخنس وسهيل عن الجوار، فأجاره المطعم بن عدي ووقف مع بنيه بالسلاح عند الكعبة حتى طاف النبي ﷺ، وقد حفظ له النبي ﷺ هذا الصنيع."] },
  { id: "srm-076", s: "seerah", g: 4, d: 5, t: ["isra-miraj", "chronology"], src: "Ibn Ḥajar, Fatḥ al-Bārī, Kitāb Manāqib al-Anṣār, chapter on the Miʿrāj",
    en: ["Which statement best describes the dating of al-Isrāʾ wa-l-Miʿrāj in the classical sources?", ["Its year and month are disputed; 27 Rajab is widespread but not agreed upon", "Sound hadith fix it at 27 Rajab of the tenth year of prophethood", "All scholars place it in Ramaḍān of the first year of prophethood", "It took place in Medina in the year after the Hijra"], "Ibn Ḥajar lists many different views on its year and month. The popular date of 27 Rajab has no agreement among the scholars. It certainly took place in Mecca before the Hijra."],
    de: ["Welche Aussage beschreibt die Datierung von al-Isrāʾ wa-l-Miʿrādsch in den klassischen Quellen am besten?", ["Jahr und Monat sind umstritten; der 27. Radschab ist verbreitet, aber nicht einhellig", "Gesunde Ḥadīthe legen sie auf den 27. Radschab des zehnten Jahres fest", "Alle Gelehrten setzen sie in den Ramaḍān des ersten Jahres", "Sie fand im Jahr nach der Hidschra in Medina statt"], "Ibn Ḥadschar führt viele verschiedene Ansichten zu Jahr und Monat an. Für das verbreitete Datum des 27. Radschab gibt es keinen Konsens der Gelehrten. Sicher ist, dass sie in Mekka vor der Hidschra stattfand."],
    ar: ["أيّ العبارات أدقّ في وصف تاريخ الإسراء والمعراج في المصادر المتقدمة؟", ["سنته وشهره مختلف فيهما، والسابع والعشرون من رجب مشهور غير متفق عليه", "حدّدته الأحاديث الصحيحة بالسابع والعشرين من رجب سنة عشر من البعثة", "أجمع العلماء على أنه في رمضان من السنة الأولى للبعثة", "وقع في المدينة في السنة التالية للهجرة"], "ذكر ابن حجر أقوالًا كثيرة في سنته وشهره، وتاريخ السابع والعشرين من رجب مشهور لكنه ليس محلّ اتفاق؛ والمقطوع به أنه كان بمكة قبل الهجرة."] },
  { id: "srm-077", s: "seerah", g: 4, d: 5, t: ["isra-miraj"], src: "Ṣaḥīḥ Muslim, Kitāb al-Īmān, on Sidrat al-Muntahā, hadith of Ibn Masʿūd",
    en: ["According to Ibn Masʿūd's report in Ṣaḥīḥ Muslim, besides the five prayers, what else was the Prophet given on the night of the Miʿrāj?", ["The closing verses of Sūrat al-Baqara", "The opening chapter, al-Fātiḥa", "The Verse of the Throne", "The last two protective sūras"], "Ibn Masʿūd reports three gifts: the five prayers, the closing verses of al-Baqara, and forgiveness of grave sins for those of his community who associate nothing with God."],
    de: ["Was erhielt der Prophet nach dem Bericht Ibn Masʿūds in Ṣaḥīḥ Muslim in der Nacht des Miʿrādsch außer den fünf Gebeten?", ["Die Schlussverse der Sure al-Baqara", "Die Eröffnungssure al-Fātiḥa", "Den Thronvers", "Die beiden letzten Schutzsuren"], "Ibn Masʿūd nennt drei Gaben: die fünf Gebete, die Schlussverse von al-Baqara und die Vergebung schwerer Sünden für jene seiner Gemeinde, die Gott nichts beigesellen."],
    ar: ["بحسب رواية ابن مسعود في صحيح مسلم، ماذا أُعطي النبي ﷺ ليلة المعراج مع الصلوات الخمس؟", ["خواتيم سورة البقرة", "فاتحة الكتاب", "آية الكرسي", "المعوذتين"], "ذكر ابن مسعود ثلاثًا: الصلوات الخمس، وخواتيم سورة البقرة، وغفران المقحمات لمن لم يشرك بالله من أمته."] },
  { id: "srm-078", s: "seerah", g: 4, d: 4, t: ["aqaba"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the second pledge of al-ʿAqaba",
    en: ["Who from the Prophet's family attended the second pledge of al-ʿAqaba while not yet a Muslim, to make sure his nephew would be protected?", ["al-ʿAbbās ibn ʿAbd al-Muṭṭalib", "Abū Ṭālib ibn ʿAbd al-Muṭṭalib", "Ḥamza ibn ʿAbd al-Muṭṭalib", "ʿAqīl ibn Abī Ṭālib"], "Ibn Isḥāq reports that al-ʿAbbās spoke first, telling the people of Yathrib to protect the Prophet fully or leave him among his own clan. Abū Ṭālib had already died, and Ḥamza was a Muslim by then."],
    de: ["Wer aus der Familie des Propheten war beim zweiten Eid von al-ʿAqaba anwesend, ohne schon Muslim zu sein, um sicherzugehen, dass sein Neffe geschützt würde?", ["al-ʿAbbās ibn ʿAbd al-Muṭṭalib", "Abū Ṭālib ibn ʿAbd al-Muṭṭalib", "Ḥamza ibn ʿAbd al-Muṭṭalib", "ʿAqīl ibn Abī Ṭālib"], "Ibn Isḥāq berichtet, dass al-ʿAbbās zuerst sprach und den Leuten aus Yathrib sagte, sie sollten den Propheten voll schützen oder ihn bei seinem Clan lassen. Abū Ṭālib war bereits gestorben, und Ḥamza war damals schon Muslim."],
    ar: ["مَن مِن آل النبي ﷺ حضر بيعة العقبة الثانية ولم يكن قد أسلم، ليستوثق لابن أخيه؟", ["العباس بن عبد المطلب", "أبو طالب بن عبد المطلب", "حمزة بن عبد المطلب", "عقيل بن أبي طالب"], "ذكر ابن إسحاق أن العباس تكلم أولًا فقال لأهل يثرب: إما أن تمنعوه تمامًا وإما أن تدعوه في قومه؛ وكان أبو طالب قد مات، وحمزة قد أسلم يومئذ."] },
  { id: "srm-079", s: "seerah", g: 4, d: 5, t: ["aqaba"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, the second pledge of al-ʿAqaba and the twelve leaders",
    en: ["At the second pledge of al-ʿAqaba the Prophet asked for twelve representatives (nuqabāʾ). How were they divided between the two tribes of Yathrib?", ["Nine from the Khazraj and three from the Aws", "Six from the Khazraj and six from the Aws", "Three from the Khazraj and nine from the Aws", "Ten from the Khazraj and two from the Aws"], "Ibn Isḥāq lists nine nuqabāʾ of the Khazraj, such as Asʿad ibn Zurāra, and three of the Aws, such as Usayd ibn Ḥuḍayr. The split ten and two is the commonly reported make-up of the first pledge, not of the nuqabāʾ."],
    de: ["Beim zweiten Eid von al-ʿAqaba verlangte der Prophet zwölf Vertreter (nuqabāʾ). Wie verteilten sie sich auf die beiden Stämme Yathribs?", ["Neun von den Chazradsch und drei von den Aus", "Sechs von den Chazradsch und sechs von den Aus", "Drei von den Chazradsch und neun von den Aus", "Zehn von den Chazradsch und zwei von den Aus"], "Ibn Isḥāq nennt neun nuqabāʾ der Chazradsch, etwa Asʿad ibn Zurāra, und drei der Aus, etwa Usaid ibn Ḥuḍair. Die Verteilung zehn zu zwei ist die verbreitete Angabe für den ersten Eid, nicht für die nuqabāʾ."],
    ar: ["في بيعة العقبة الثانية طلب النبي ﷺ اثني عشر نقيبًا. كيف توزعوا على قبيلتي يثرب؟", ["تسعة من الخزرج وثلاثة من الأوس", "ستة من الخزرج وستة من الأوس", "ثلاثة من الخزرج وتسعة من الأوس", "عشرة من الخزرج واثنان من الأوس"], "عدّ ابن إسحاق تسعة نقباء من الخزرج كأسعد بن زرارة، وثلاثة من الأوس كأسيد بن حضير؛ أما العشرة والاثنان فهو المشهور في عدد أصحاب البيعة الأولى لا النقباء."] },
  { id: "srm-080", s: "seerah", g: 4, d: 4, t: ["hijra", "cave-of-thawr"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb Manāqib al-Anṣār, the Hijra of the Prophet; Ibn Hishām, al-Sīra al-Nabawiyya",
    en: ["Who guided the Prophet and Abū Bakr along the route to Yathrib after the cave of Thawr?", ["ʿAbdullāh ibn Urayqiṭ, a hired guide not yet Muslim", "ʿĀmir ibn Fuhayra, who grazed the sheep", "ʿAbdullāh ibn Abī Bakr, who brought the news", "Surāqa ibn Mālik, after he turned back"], "al-Bukhārī describes a skilled guide of Banū al-Dīl who still followed the religion of Quraysh, hired and trusted with the two camels; Ibn Isḥāq names him ʿAbdullāh ibn Urayqiṭ (or Arqaṭ). ʿĀmir rode with them, but the guide led the way."],
    de: ["Wer führte den Propheten und Abū Bakr nach der Höhle Thaur auf dem Weg nach Yathrib?", ["ʿAbdullāh ibn Uraiqiṭ, ein angeheuerter, noch nicht muslimischer Führer", "ʿĀmir ibn Fuhaira, der die Schafe weidete", "ʿAbdullāh ibn Abī Bakr, der die Nachrichten brachte", "Surāqa ibn Mālik, nachdem er umgekehrt war"], "Al-Buchārī beschreibt einen kundigen Führer der Banū ad-Dīl, der noch der Religion der Quraisch folgte, angeheuert und mit den beiden Kamelen betraut; Ibn Isḥāq nennt ihn ʿAbdullāh ibn Uraiqiṭ (oder Arqaṭ). ʿĀmir ritt mit, doch der Führer wies den Weg."],
    ar: ["مَن دلّ النبي ﷺ وأبا بكر على طريق يثرب بعد غار ثور؟", ["عبد الله بن أريقط، دليل مستأجر لم يكن قد أسلم", "عامر بن فهيرة راعي الغنم", "عبد الله بن أبي بكر ناقل الأخبار", "سراقة بن مالك بعد رجوعه"], "وصف البخاري دليلًا خرّيتًا من بني الديل على دين كفار قريش استأجراه وأمّناه على الراحلتين، وسمّاه ابن إسحاق عبد الله بن أريقط (أو أرقط)؛ وقد صحبهما عامر لكن الدليل هو الذي سلك بهم الطريق."] },
];
